export default [{"id":187,"question":"هل يجوز لي أن أتمتع في اليوم الثامن؟","title":"هل يجوز التمتع في اليوم الثامن؟","answer":"الجواب: نعم، إذا دخلت البلد، وجئتَ من بلدك الثامن وأنت مُلبٍّ بالعمرة؛ تطوف وتسعى، وإن كنتَ مُلبِّيًا بالحج تجعلها عمرةً، تنويها عمرة، فتطوف وتسعى وتُقصّر وتحلّ كما أمر النبيُّ أصحابَه، ثم تُلبي وتغتسل بعد ذلك، تستريح وتغتسل وتتطيَّب، ثم تُلبي بالحج، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/3760/هل-يجوز-التمتع-في-اليوم-الثامن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0191.mp3","categories":["الإحرام"]},{"id":383,"question":"أحرمتُ من مدينة جدة بحجٍّ، وأردتُ أن أستبدل الإحرامات التي أحرمتُ فيها أول مرةٍ لاتِّساعها، فهل يجوز؟","title":"حكم استبدال ملابس الاحرام أثناء الإحرام","answer":"الجواب: لا حرج في إبدال الملابس ليلة الإحرام للرجل والمرأة جميعًا، لا حرج أن يستبدلها بجديدٍ أو بغسيلٍ، لا حرج في ذلك مطلقًا.\nأما إحرامه من جدة فهذا فيه تفصيلٌ: إن كان من أهلها المقيمين فيها فلا بأس، وإن كان ممن ورد إليها ناويًا الحجَّ والعمرة فليس له الإحرام منها، بل عليه أن يُحرم من الميقات الذي يمر عليه، الذي جاء من مصر أو الشام أو الغرب يُحرم من الجحفة ومن رابغ، والذي جاء من نجد ونحوها يُحرم من وادي قرن، وهكذا، ليس له الإحرام من جدة، بل يلزمه أن يُحرم من الميقات الذي يمر عليه، جوًّا أو برًّا أو بحرًا. أما إذا كان من أهل جدة أو من المقيمين فيها للعمل ونحوه، ثم لما جاء الحج عزم على الحج؛ يُحرم منها كغيره، كالمقيم في أم السلم، وكالمقيم في بحرة، وكالمقيم في الشرائع، كل واحدٍ يُحرم منها من محلِّه؛ لقوله ﷺ لما ذكر المواقيت قال: هنَّ لهنَّ ولمن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحج أو العمرة، ثم قال عليه الصلاة والسلام: ومَن كان دون ذلك فمهلّه من حيث أنشأ، حتى أهل مكة من مكة.","link":"https://binbaz.org.sa/fatwas/4713/حكم-استبدال-ملابس-الاحرام-اثناء-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0439.mp3","categories":["الإحرام"]},{"id":392,"question":"جئتُ من باكستان، وأحرمتُ من جدة، فما الحكم؟","title":"ما حكم من جاء من باكستان وأحرم في جدة؟","answer":"الجواب: هذا فيه تفصيل: إن كنتَ حين جئتَ من باكستان ناويًا الحجَّ فالواجب عليك الإحرام من الميقات الشرعي، وهو ميقات الشرقيين، ميقات نجد ومَن كان على سبيلهم؛ لأن الهند وباكستان شرقيتان، فميقاتهما وادي قرن. إلا إذا جاءوا من طريق المدينة فميقاتهم المدينة، أو من طريق اليمن فميقاتهم يلملم، أما إذا جاءوا من الطريق الشرقي فإنَّ ميقاتهم وادي قرن، فإذا جاوزه وأحرم من جدة فعليه دمٌ؛ لأنه جاوز الميقات. أما إن كان أتى جدة لحاجاتٍ، ما قصد حجًّا ولا عمرةً، وإنما جاء لحاجاتٍ أخرى، ثم أنشأ نية الحج أو العمرة من جدة؛ فهذا يُحرم من جدة كما تقدم؛ لأنه ما نوى الحجَّ ولا العمرة قبل ذلك.","link":"https://binbaz.org.sa/fatwas/4777/ما-حكم-من-جاء-من-باكستان-واحرم-في-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0448.mp3","categories":["الإحرام","المواقيت"]},{"id":403,"question":"ما حكم مَن يتم الصلاة في عرفات؟","title":"ما حكم مَن يتم الصلاة في عرفات؟","answer":"الجواب: لا، السُّنة لا يتم، لا يخالف الناس، السُّنة أن يُصلي مع الناس اثنتين، ويد الله مع الجماعة، وهذه السنة الظاهرة، فلا يجتهد اجتهادًا يُخالف السنة الظاهرة، فالاحتياط في اتِّباع السنة.","link":"https://binbaz.org.sa/fatwas/4813/ما-حكم-من-يتم-الصلاة-في-عرفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0461_2.mp3","categories":["الوقوف بعرفة","الإحرام"]},{"id":617,"question":"بعض القادمين من خارج المملكة إذا وصلوا جدة يقولون نجلس ثلاثة أيام في جدة ثم نحرم من الميقات؟","title":"حكم من جاوز الميقات للبقاء في جدة أولاً","answer":"الجواب: يلزمهم أن يعودوا إلى الميقات ويحرمون من الميقات وهم جايين للحج والعمرة يلزمهم يعودون ليحرموا من الميقات لا يجوز لهم تجاوز الميقات، الرسول ﷺ قال: هن لهن ولمن أتى عليهن من غير أهلهن لمن أراد الحج أو العمرة فلا بدّ إن أرادوا الحج أو العمرة ومروا من الميقات أن يحرموا منه فإن تجاوزوه يعودون إليه فإن أبوا ولم يعودوا؛ لزمهم دم.","link":"https://binbaz.org.sa/fatwas/6457/حكم-من-جاوز-الميقات-للبقاء-في-جدة-اولا","audio":"undefined","categories":["المواقيت","الإحرام"]},{"id":621,"question":"القادمون من السودان أين ميقاتهم؟","title":"أين الميقات للقادمين من السودان؟","answer":"الجواب: إذا حاذوا الجُحْفة أحرموا من محاذاة الجحفة، فإذا جاءوا من طريق لا يحاذون فيه الميقات أحرموا من جدة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6483/اين-الميقات-للقادمين-من-السودان","audio":"https://files.zadapps.info/binbaz.org.sa/maram189.mp3","categories":["المواقيت","الإحرام"]},{"id":622,"question":"من ذهب إلى جدة لغرض أو  للسياحة وهو قاصد الخروج إلى الرياض للعمرة لكن قال أذهب أولاً إلى جدة ثم نعتمر؟","title":"حكم من أراد العمرة لكن يريد زيارة جدة قبلها","answer":"الجواب: إذا قضى حاجته من جدة يرجع للميقات، الميقات الذي مر به إذا كان ناويًا قبل أن يمر منه ناويًا من بلده، وإما يُحْرم مُعْجَّلاً من الميقات ويؤدي العمرة ثم يروح لجدة، وإلا إذا قضى غرضه من جدة يرجع إلى الميقات.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6484/حكم-من-اراد-العمرة-لكن-يريد-زيارة-جدة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/maram190 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":623,"question":"إذا جاوزت الطائرة الميقات، فإذا وصل المطار هل يجوز أن يذهب إلى رابغ؟","title":"ماذا يفعل راكب الطائرة إذا جاوز الميقات؟","answer":"الجواب: لا، يحرم من الميقات الذي مر عليه.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6486/ماذا-يفعل-راكب-الطاىرة-اذا-جاوز-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/maram191  - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":625,"question":"إذا كان المسافر بالطائرة وصلوا بعد نصف ساعة فمروا من فوق الميقات ولبى يخشى أن يفوته الميقات؟","title":"حكم احتياط المحرم على الطائرة في الميقات","answer":"الجواب: إذا احتاط لا بأس، إذا احتاط قبل أن يصل الميقات لا بأس، الاحتياط مطلوب.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6491/حكم-احتياط-المحرم-على-الطاىرة-في-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/maram193 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":626,"question":"النبي ﷺ هو الذي وَقَّت رابغ؟","title":"هل الجحفة ورابغ شيء واحد في المواقيت؟","answer":"السؤال: هو الذي وقت الجُحْفة، والجحفة هي ورابغ شيء واحد، لكن رابغ أرفق للناس من الجحفة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6492/هل-الجحفة-ورابغ-شيء-واحد-في-المواقيت","audio":"https://files.zadapps.info/binbaz.org.sa/maram194 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":627,"question":"الإحرام قبل الميقات؟","title":"ما حكم الإحرام قبل الميقات؟","answer":"الجواب: مكروه، وقد أحرم بعض السلف من الشام، لكن الأوْلى ترك ذلك واتباع السُّنة، لا يحرم إلا من الميقات.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6493/ما-حكم-الاحرام-قبل-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/maram195 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":628,"question":"الإحرام عقب الصلاة، أي صلاة مفروضة أو نافلة؟","title":"هل يكون الإحرام عقب صلاة فرض أو نافلة؟","answer":"الجواب: نعم، إذا كانت فريضة تُغْنِي، النبي ﷺ أحرم بعد الظهر. وإذا كان ما في فريضة؛ شُرع له أن يصلي ركعتي وضوء ثم يُحْرِم بعدهما بعد ركوب الدابة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6494/هل-يكون-الاحرام-عقب-صلاة-فرض-او-نافلة","audio":"https://files.zadapps.info/binbaz.org.sa/MARAM196 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":633,"question":"الركعتين عند الإحرام سُنة؟","title":"ما حكم الركعتين عند الإحرام؟","answer":"الجواب: إذا توضأ صلى ركعتي الوضوء. أما الجمهور: يرون أنها سُنة مطلقًا، لكن الأفضل أنه إذا توضأ يصلي ركعتين سنة الوضوء.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6520/ما-حكم-الركعتين-عند-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/maram201 - 03 - .mp3","categories":["صلاة التطوع","الإحرام"]},{"id":634,"question":"في واحد نوى التمتع هل يقدر يغير إلى قِران؟","title":"متى يجوز تغيير النية من التمتع إلى قِران؟","answer":"الجواب: إذا كان معه الهَدْى يغير إلى قِران، وإذا كان ما معه هدي فالسُّنة يطوف ويسعى ويقصِّر ويَحلّ، ولا يُغَيِّر، هذه هي السنة: إذا لبى بالعمرة يطوف ويسعى ويقصِّر ويَحلّ، وإن كان لبى بالحج السُّنة أن يجعلها عمرة أيضاً، حتى لو لبى بالحج يفسخها إلى عمرة يطوف ويسعى ويقصر ويجعلها عمرة ويَحلّ، كما أمر النبي ﷺ الصحابة بذلك، إلا من ساق الهدي؛ من كان مع هدي إبل وإلا بقر وإلا غنم فهذا يُحْرِم بالحج والعمرة جميعًا ولا يَحلّ إلا في أيام النحر حتى ويَحلّ من حجه أو عمرته.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6553/متى-يجوز-تغيير-النية-من-التمتع-الى-قران","audio":"https://files.zadapps.info/binbaz.org.sa/maram202 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":667,"question":"من عقد النية يوم عرفة في عرفة بالحج، كسوّاق نوى أن يحج وهو في وسط عرفة يوم عرفة، هل له الحج؟","title":"ما حكم من نوى الحج يوم عرفة؟","answer":"الجواب: يجزئه الحج ؛ لأنه أدرك عرفة؛ يُكَمِّل أعماله.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6702/ما-حكم-من-نوى-الحج-يوم-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/maram235 - 03 - .mp3","categories":["الوقوف بعرفة","الإحرام"]},{"id":720,"question":"شخصٌ جاء إلى جدة عن طريق المدينة، فلما مكث بجدة يومان أراد أن يأخذ عمرةً، فهل يُحْرِم من جدة وليس عليه شيءٌ؟ أم أنَّ عليه دمًا باعتبار أنه لم يُحْرِم من الميقات؟","title":"حكم من جاء إلى جدة ثم أراد العمرة","answer":"الجواب: هذا فيه تفصيل ينبغي أن نفهمه جيدًا: هذا الذي جاء من المدينة إلى جدة، أو من الرياض إلى جدة، أو من المنطقة الشرقية إلى جدة، أو من الشام إلى جدة، أو غير ذلك، إن كان ما أراد عمرةً، ما نوى عمرةً، جاء لحاجةٍ في جدة، ما أراد عمرةً ولا حجًّا، جاء لحاجةٍ: يزور أخًا له، يزور صاحبًا له، للتِّجارة، لغير هذا من الحاجات، فهذا له أن يُحْرِم من جدَّة؛ لأنه ما نوى إلا في جدة، إذا نوى العمرة في جدة يُحْرِم من جدة؛ لأنه حين مرَّ بالميقات ما كانت عنده نيَّة، حينما مشى من المدينة أو من الرياض أو من الدمام أو من الشام أو غير ذلك ما قصد عمرةً ولا حجًّا، إنما أراد جدة لمصلحةٍ وحاجةٍ، فهذا إذا نوى في جدة يُحرم منها؛ لقول النبي ﷺ لما وقَّت المواقيت: هنَّ لهنَّ ولمن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحجَّ والعمرةَ، ثم قال عليه الصلاة والسلام: ومَن كان دون ذلك فمهلّه من حيث أنشأ، مهلّه يعني: محل إهلاله، من حيث أنشأ، حتى أهل مكة من مكة.\nيدخل في هذا مَن جاء من المدينة إلى جدة ما أراد العمرة، لكن لما وصل جدة وأقام بها قال: أنا قريبٌ، أريد أن آخذ عمرةً؛ لا بأس، يُحرم من جدَّة؛ لأنه إنما أنشأ بها، أو جاء من الرياض أو من الدمام أو من الإحساء أو من غير ذلك إلى جدة يزور قريبًا له، ما نوى عمرةً، أو للتِّجارة ما نوى عمرةً، ثم طرأ عليه في جدة أن يعتمر؛ يُحرم منها.\nأما إنسانٌ جاء من الرياض أو من المدينة لقصد العمرة، فهذا لا يتجاوز الميقات: إن كان من المدينة يُحرم من ميقات المدينة، وإن كان من الرياض أو الإحساء أو غيرها يُحرم من ميقات أهل نجدٍ: السيل، من طريق الطائف، إذا كان من طريق الطائف هو السيل المعروف، ولا يتجاوز ذلك إلا بإحرامٍ، إذا جاوزه وأحرم من جدة وهو ناوٍ العمرة حين توجَّه؛ فهذا عليه دمٌ، يُذبح في مكة للفقراء؛ لأنه ترك واجبًا وهو الإحرام من الميقات، والله أعلم.","link":"https://binbaz.org.sa/fatwas/20561/حكم-من-جاء-الى-جدة-ثم-اراد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0519فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["المواقيت","الإحرام"]},{"id":859,"question":"إنَّ أهل المغرب الإسلامي يُعانون من مشكل الإحرام من الميقات المُخصص لهم، حيث يمرون عليه وهم في الجو، حيث لا يستطيعون الإحرام في الطائرة، ولا في المطارات، وقد أفتى بعضُهم لهم بالإحرام في جدة، ما رأيكم في هذه الفتوى؟","title":"حكم الإحرام بعد الميقات لتعذُّره بالطائرة","answer":"الجواب: قد كتبنا عليها ردًّا، وكتبنا لأخينا الذي أفتاهم الشيخ عبدالله قنو: هذا غلط، وليس في الإحرام بالطائرة مشقَّة، الإحرام: لبيك عمرة، لبيك حجًّا، ما فيه مشقَّة كلام: اللهم لبيك حجًّا، أو: اللهم لبيك عمرة، هذا ما فيه مشقَّة على أحدٍ، إذا وصل الميقات أو دنا من الميقات وخاف أن يتجاوزه قبل أن يصل إليه يخاف: يُلبي ولو قبله حتى يحتاط لإحرامه.\nوأما الغسل والتَّطيب ما هو بلازمٍ، وإن تطيب في الطائرة قبل أن يُحرم فهو ميسورٌ، يحطّ الطيب جنبه، أو معه، أو في شنطته، ويتطيب قبل أن يُحرم، والغسل ما هو بلازمٍ، وفي إمكانه أن يغتسل في بيته قبل أن يُحرم، يغتسل في بيته قبل أن يركب الطائرة، ولو مكث في الطائرة يومًا أو نصف يومٍ، يغتسل في بيته، والغسل سُنَّة، ما هو بلازمٍ.\nكذلك لباس الإحرام يلبسه في بيته، يلبسه في الطائرة قبل أن يدخل الميقات، وهو في حال السعة، يلبس الإزار والرداء، ويلبس الإزار في بيته أيسر عليه، يعدّه في بيته، ويلبس ملابس فوق الإزار، فإذا جاء حذو الميقات خلع الملابس ولبس الرداء كله، مُيَسَّرٌ أن نفعل هذا، الإنسان يفعل في بيته ما يتيسَّر: يتطيب، ويغتسل، ويلبس الإزار وثيابه فوق الإزار، فإذا قرب من الميقات خلع الملابس ولبس الرداء ولبَّى، وليس في هذا مشقَّة، ولا يجوز تجاوز الميقات أبدًا، والفتوى غلط.","link":"https://binbaz.org.sa/fatwas/20893/حكم-الاحرام-بعد-الميقات-لتعذره-بالطاىرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0688من لايستطيع أن يحرم في الطائرة أو المطار فهل يجوز له أن يحرم من جدة؟ ابن باز فتاوى المحاضرات.mp3","categories":["المواقيت","الإحرام"]},{"id":871,"question":"قد ذكرتُم جزاكم الله خيرًا أنه لا يجوز تجاوز الميقات إلا بالإحرام، فما الحكم في مثل حالتنا، حيث أحرمنا من جدة، علمًا بأنه أفتانا بعضُ الناس بجواز ذلك، وأنَّ الإحرام جائزٌ من جدة، وبالطائرة، ونسبوا ذلك لبعض أهل العلم؟ أفتونا مأجورين.","title":"حكم من تجاوز ميقات الإحرام المحدد له","answer":"الجواب: إذا كنتم جئتُم بقصد العمرة من بلادكم ومررتُم على المواقيت ناوين العمرة، فعليكم دمٌ، والفتوى هذه لا وجهَ لها، قد أجمع العلماء جميعًا على أنَّ الواجب على مَن مرَّ على الميقات ناويًا الحجَّ والعمرة يُحرم منه، هذا بإجماع أهل العلم؛ لقوله ﷺ في حديث ابن عباس، يقول ابن عباس: \"وقَّت النبيُّ ﷺ لأهل المدينة ذا الحليفة، ولأهل الشام الجحفة، ولنجد قرن المنازل، ولأهل اليمن يلملم: هنَّ لهنَّ ولمن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحجَّ والعمرةَ\".\nفإذا كنتم مررتُم عليها بنية العمرة فقد أخطأتُم في تجاوزها، وعليكم دمٌ، مع التوبة والاستغفار، وليس كل فتوى تكون جديرةً بالأخذ، لا بد للإنسان أن يتثبت في الأمور، ولا يسأل إلا أهل العلم المعروفين بالعلم والفضل، والخشية لله، والورع، وقلة التسرع، يحتاط لدينه.\nوقد أجمع العلماءُ على أنَّ هذه المواقيت لا يجوز تجاوزها إلا بإحرامٍ، وإنما اختلفوا: هل عليه دمٌ أم لا؟\nالجمهور على أنَّ مَن جاوزها -عليه أكثر العلماء- عليه دمٌ؛ لقول ابن عباسٍ رضي الله تعالى عنهما: \"مَن ترك نُسُكًا أو نسيه فليُهرق دمًا\"، وهذا كلامٌ جيدٌ، وبعض أهل العلم جعل له حكم الرفع؛ لأنه لا يُقال من جهة الرأي.\nس: يصعب عليهم الآن الدَّم، ما عندهم مقدرة؟\nالشيخ: بعد ذلك يرسل، ولو بعد ذلك، أو يصوم مَن عجز عشرة أيام، أو يُرسل من بلاده مع الحجّاج، أو مع غير الحجّاج، أو يُوكّل في مكة مَن يذبحه ولو بعدما يصل إلى بلاده، ما هو بلازمٍ الآن: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/20899/حكم-من-تجاوز-ميقات-الاحرام-المحدد-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0694فما الحكم فمن أحرم من جدة بعد تجاوز الميقات للضرورة نباءً على فتاوى بالجواز؟ ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":902,"question":"هل يقع من أهل مكة تمتع وقران؟","title":"هل يقع من أهل مكة تمتع وقران؟","answer":"الشيخ: نعم، لا بأس، لكن ليس عليهم هدي التمتع والقران، فلهم أن يمتعوا بالعمرة في أشهر الحج، ولهم أن يقرنوا بينهما، لكن الأفضل لهم الحج المفرد؛ لأنَّ الله وسَّع لهم العمرة، متى شاءوا اعتمروا، فلو اعتمروا في أشهر الحج فلا بأس.","link":"https://binbaz.org.sa/fatwas/20941/هل-يقع-من-اهل-مكة-تمتع-وقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0737هل يقع من أهل مكة تمتع وقِران؟ ابن باز فتاوى المحاضرات.mp3","categories":["المواقيت","الإحرام"]},{"id":1074,"question":"أنا من أهل الطائف، وفي مرةٍ نويتُ العمرة من الطائف، ولكن كان هناك بعض الأقرباء في جدة، فذهبتُ إلى جدة وأحرمتُ من هناك، فهل عليَّ في ذلك شيءٌ؟","title":"حكم الإحرام من جدة لمن نوى عمرةً بالطائف","answer":"الجواب:\nإذا كنتَ أردتَ العمرة من الطائف وتساهلتَ ورحت واعتمرتَ من جدَّة عليك دمٌ؛ لأن الواجب عليك الإحرام من الطائف، من ميقات الطائف. أما إذا كنتَ حين ذهبتَ إلى جدة ما نويتَ العمرة، أو عندك تردُّدٌ ولم تعزم إلا من جدَّة؛ فليس عليك شيءٌ. أما إذا عزمتَ على العمرة وصممتَ عليها فعليك أن تُحرم من الميقات، وإذا ذهبتَ إلى جدة لا تُحرم من جدة، ارجع إلى الميقات، واحرم من الميقات، فإن أحرمتَ من جدَّة فعليك دمٌ؛ لأنك جاوزتَ الميقات وأنت عازمٌ على العمرة.","link":"https://binbaz.org.sa/fatwas/21143/حكم-الاحرام-من-جدة-لمن-نوى-عمرة-بالطاىف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0939تويت العمرة من الطائف وذهبت إلى جدة لزيارة أقربائي وأحرمت من هناك فهل عليَّ في ذلك شيء؟.mp3","categories":["المواقيت","الإحرام"]},{"id":1226,"question":"رجلٌ تجاوز الميقات دون إحرامٍ، ولم يجد قيمةَ الدم، ولا يستطيع الصيام، فماذا يفعل؟","title":"حكم من لا يستطيع الفدية ولا الصيام في الحج","answer":"الجواب:\nيبقى عليه الدم أو الصيام حتى يستطيع، إذا أحرم من دون الإحرام، جاوز الميقات ولم يُحرم، وأحرم من داخل مكة، أو من الطريق، فقد أساء، وعليه التوبة إلى الله، وعليه دمٌ متى قدر، فإن عجز يصوم عشرة أيام متى قدر، مثل: سائر الديون، يبقى دينًا كسائر الديون، فإن أوفى الله عنه في الدنيا وإلا فمعذورٌ، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21286/حكم-من-لا-يستطيع-الفدية-ولا-الصيام-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1029رجل تجاوز الميقات دون أحرام ولم يجد قيمة الدم ولا يستطيع الصيام فما يفعل؟ ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":1230,"question":"جئتُ من مصر للعمل بمكة منذ أربعة شهور، فهل لي أن أُهلّ بالإفراد بالحج من منزلي بالعزيزية؟ أرجو التوضيح، وجزاكم الله خيرًا.","title":"من أين يُحْرِم بالحج أهل مكة والمقيمون فيها؟","answer":"الجواب:\nنعم، إذا قدم الحاجُّ وأدَّى العمرةَ فإنه إذا جاء وقتُ الحجِّ يوم الثامن يُلبي بالحج من منزله إن كان في الأبطح أو في داخل مكة، الصحابة  الذين حلّوا أمرهم النبيُّ ﷺ أن يُحرموا من منازلهم في الأبطح، أن يُهلُّوا بالحج من منازلهم، فالذي أتى مكةَ وفرغ من العمرة وجلس إلى وقت الحج يُحرم من منزله، وهكذا أهل مكة والمقيمون فيها من غير أهلها: إذا جاء وقتُ الحجِّ أحرموا من منازلهم، وليس هناك حاجة إلى الدخول إلى المسجد الحرام، ولا يُشرع ذلك، بل يُحْرِم من مكانه، ويتوجَّه إلى مِنى يوم الثامن حتى يُصلي بها الظهر والعصر والمغرب والعشاء والفجر، ولا يُشرع لهم الدُّخول إلى مكة ليطوفوا، ليس على هذا دليلٌ.","link":"https://binbaz.org.sa/fatwas/21282/من-اين-يحرم-بالحج-اهل-مكة-والمقيمون-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1025قدمت من مصر لمكة منذ أربعة أشهر فهل لي أن أهلَّ بالإفراد من منزلي بالعزيزة ارجو التوضيح؟ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":1291,"question":"يعلم سماحتكم أنه يُكلَّف بعض الأطباء بالعمل في خدمة الحجيج في فترة الحج، فهل يجوز للطبيب المُكلَّف بالعمل أن يُحْرِم من مكان عمله في مكة؟","title":"حكم إحرام الطبيب في الحج من مكان عمله","answer":"الجواب:\nنعم، له أن يُحرم إذا كان دخل من دون إحرامٍ، ما نوى إحرامًا، وإنما بدا له الإحرام بعد ذلك، يُحرم من مكانه خارج الحرم، من عرفات إن كان فيها، من الجعرانة إذا كان لعمرةٍ.  أما إذا كان للحج يُحرم من مكانه، ولو في منى، ولو أنه في منى يُحرم من مكانه إذا كان في الحجِّ، بشرط أنه دخل ما عنده نيَّة.  أما إذا كان داخلًا حين مرَّ بالميقات وهو ناوٍ يُحرم من الميقات، وإن كان ما أحرم يرجع إليه ويُحرم منه.\nأما إن كان لا، جاء للعمل، ما عنده نية: لا حج، ولا عمرة، جاء للعمل، ثم بدا له، سُمح له أن يحجَّ أو يعتمر: إن كان عمرةً يُحرم من الحلِّ للعمرة: الجعرانة أو التَّنعيم أو عرفات، من خارج الحرم، خارج الأميال، يخرج إلى الحلِّ ويُحرم من الحلِّ. أما إن كان حجَّ فيُحرم من مكانه في منى في يوم الثامن، أو يوم عرفة، أو في عرفات يُحرم منها والحمد لله.\nس: طيِّب، لو ما سمحت له الجهة التي ابتعثته للحجِّ؟\nالشيخ: لا يُحْرِم، إذا كان ما سمحوا له لا يُحرِم، يعمل ولا يُحْرِم، عليه السمع والطاعة؛ لأنه إذا ما أحرم يكون أفْرَغَ للعمل.","link":"https://binbaz.org.sa/fatwas/21344/حكم-احرام-الطبيب-في-الحج-من-مكان-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1087يكلف بعض الأطباء في خدمة الحجاج فهل يجوز له آن يحرم من مكان عمله؟ ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":1297,"question":"هل يجوز (للمرأة) الكشف في الحج؟","title":"هل يجوز كشف المرأة وجهها في الحج؟","answer":"الجواب:\nلا تلبس النقاب، ولكن تستر وجهها بغير النقاب: بخمارٍ ونحوه مما يستر الوجه، على وجهٍ لا يمنعها السير، تجعل غطاءً لا يمنعها السير والنظر إلى الطريق، لكن غير النقاب.\nالنقاب: البُرقع الذي يُجعل على الوجه، الخاص بالوجه، يكون فيه نقب أو نقبان، هذا يُسمَّى: نقابًا، منع النبيُّ ﷺ من لبسه في حقِّ المحرمة، والقفازان كذلك في يديها حال إحرامها، ولكن تُغطي يديها ووجهها بغير ذلك، قالت عائشةُ رضي الله عنها: \"كنا مع النبي ﷺ في الحجِّ، فإذا دنا منا الرجال سدلت إحدانا جلبابها على وجهها\"، أو قالت: \"خِمارها على وجهها\"، \"فإذا بَعُدُوا كَشَفْنا\".","link":"https://binbaz.org.sa/fatwas/21372/هل-يجوز-كشف-المراة-وجهها-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1115سائلة تقول هل يجوز كشف الوجه في الحج؟ ابن باز فتاوى.mp3","categories":["المواقيت","الإحرام"]},{"id":1301,"question":"نحن بعض منسوبي المدرسة، كان أحد زملائنا في قسم التربية الإسلامية في المناهج قال إن أنساك الحج اثنان فقط، هما: القِرَان، والتَّمتع، وليس هناك نُسُكٌ ثالث كما يزعم البعضُ، ويُسميه: الإفراد، وقد أسمعنا مجموعةً من الأدلة، وقول بعض أهل العلم، مثل: الشوكاني، وابن حزم، وغيره، وقال: ارجعوا إلى كتاب \"البخاري\" و\"زاد المعاد\"، فما القول الراجح في هذه المسألة أثابكم الله؟","title":"ما الصواب في أنواع أنساك الحج؟","answer":"الجواب:\nهذا غلطٌ باطلٌ، أجمع العلماء على أن الأنساك ثلاثة: حج مفرد، وقران، وتمتع، بإجماع أهل  العلم، وقد خيَّر النبيُّ ﷺ الصحابة في الميقات في حجة الوداع بين ذلك.  ولكن يُستحب لمن قدم مكة وليس معه هدي وقد أحرم بالحج أو بالقِرَان أن يجعلهما عمرةً، سواء كان حجًّا أو قِرَانًا، إذا كان ما معه هَدْي؛ فالمشروع له أن يجعلها عمرةً: يطوف ويسعى ويُقَصِّر، وإلا فالحج غير منسوخ، نُسُكُه مستقل، والقران نُسُكُه مستقل.\nوقد أقر النبيُّ ﷺ عروة بن المضرس على إحرامه بالحج، ولم يأمره بفسخه، المقصود أنَّ الفسخ سُنة، على الصحيح سُنة، وقال بعضُهم: إنه خاصٌّ بالصحابة، كما قال أبو ذرٍّ: إنه خاصٌّ بنا، والصواب أنه ليس خاصًّا بالصحابة، لكن يُستحب لمن قدم مكة مُحْرِمًا بالحج مُفردًا أو قارنًا وليس معه هدي: لا إبل، ولا بقر، ولا غنم، أن يجعلها عمرةً: يطوف ويسعى ويُقَصِّر ويحلّ، أما أنه زعم أنه باطلٌ، وأنه نسخ؛ فهذا غلطٌ من قائله.","link":"https://binbaz.org.sa/fatwas/21368/ما-الصواب-في-انواع-انساك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1111رجل يقول أن أنساك الحج أثنان القران والتمتع وليس هناك نسك ثالث فما رأيكم؟.mp3","categories":["المواقيت","الإحرام"]},{"id":1565,"question":"إذا كان الشخص من أهل الرياض وذهب إلى المدينة زيارةً، من أين يُحْرِم إذا أراد العمرة؟","title":"حكم مَن أتى من بلده للمدينة ثم أراد العمرة","answer":"الجواب:\nمن ميقات المدينة، إذا أراد العمرة وهو في المدينة يُحرم من ميقات المدينة، وإذا أراد العمرة وهو في الطائف يُحرم من ميقات الطائف، وإذا أراد العمرة وهو في اليمن يُحرم من ميقات اليمن.\nس: وهو في الرياض أحسن الله إليك؟\nج: نعم، ولو، طالما أنه توجَّه إلى المدينة يُحرم من ميقات المدينة.","link":"https://binbaz.org.sa/fatwas/21668/حكم-من-اتى-من-بلده-للمدينة-ثم-اراد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أتى من الرياض إلى المدينة ثم أراد العمرة.mp3","categories":["المواقيت","الإحرام"]},{"id":1740,"question":"قدم إلى مكة مُفْرِدًا، وطاف طواف القدوم، وسعى وقدَّم السعي، وبعدما قدَّم السعي قال: لماذا لا أُحوّلها إلى عمرةٍ وأتمتع، فهل له ذلك مع أنه قد نوى الإفراد؟","title":"حكم تحويل نية الحج من الإفراد إلى التمتمع","answer":"الجواب:\nهذا الأفضل، يُقَصِّر ويحلّ، ولو.\nس: يعني: له ذلك؟\nج: نعم، نية عمرة.","link":"https://binbaz.org.sa/fatwas/21847/حكم-تحويل-نية-الحج-من-الافراد-الى-التمتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يصنع من أراد تحويل النية من المفرد إلى التمتمع.mp3","categories":["المواقيت","الإحرام"]},{"id":2242,"question":"الرجال في الحج هل يجوز لهم أن يُغيّروا النيةَ بعد الدخول في نُسُكٍ معينٍ إلى نية نُسُكٍ آخر؟","title":"حكم تغيير النية في الحج مِن نُسُك إلى آخر","answer":"الجواب:\nحسب الشرع، إذا دخل في حجٍّ أو حجٍّ وعمرةٍ فله أن يجعلهما عمرةً، وهو السنة، فيفسخهما عمرةً، أمَّا إذا أحرم بعمرةٍ فليس له أن ينتقل عنها، لكن له أن يُدْخِل عليها الحجّ فيكون قارنًا.\nس: مَن حجَّ متمتّعًا هل له أن يجعل العمرةَ لشخصٍ والحجَّ لشخصٍ؟\nج: نعم لا بأس، يُهلّ بالعمرة لنفسه، وبعد التحلل يُلبي بالحج عن أبيه، أو عن أمه، أو عن زوجته.\nس: كيف يكون الفسخُ من حجٍّ إلى عمرةٍ؟\nج: بالنية.\nس: والإحرام؟\nج: لبَّى بالحجِّ من الميقات، أو بالحجِّ والعمرة جميعًا، ثم لما وصل مكةَ جعلها عمرةً؛ فطاف وسعى وقصَّر أو حلق، مثلما أمرهم النبيُّ ﷺ إذا لم يكن معه هدي.","link":"https://binbaz.org.sa/fatwas/22365/حكم-تغيير-النية-في-الحج-من-نسك-الى-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تغيير النية في الحج من نسك إلى نسك آخر.mp3","categories":["المواقيت","الإحرام"]},{"id":2718,"question":"رجل أتى من الكويت وزار المدينة وأحرم من ميقات أهل المدينة، وكان هذا قبل رمضان، يريد أن يعتمر في رمضان؟","title":"مِن أين يُحْرِم مَنْ أتى مِن الكويت للمدينة؟","answer":"الجواب: يعتمر مِنْ الحِلّ، من التنعيم أو من عرفات أو من الجعرانة، من الحِلّ خارج الحدود.\nس: لا يشترط أن يكون من...؟\nالشيخ: ما هو بلزوم لا، لمّا صار في مكة وأدى العمرة، إذا أدى عمرة يخرج إلى الحِلّ مثلما فعلت عائشة اعتمرت من المدينة، ثم أحرمت بالعمرة الثانية من التنعيم، بأمر النبي عليه الصلاة والسلام.\nس: الذهاب إلى جدة هل يُحْرِم؟\nالشيخ: إذا ذهب إلى جدة أو غيرها ما في بأس، لكن الله يسّر عليه الأقرب.\nس: من قال إن هذا خاص بالحائض؟\nالشيخ: مِنْ كِيسِه، إن كان كِيسُ الناس يُطاع وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7].","link":"https://binbaz.org.sa/fatwas/22861/من-اين-يحرم-من-اتى-من-الكويت-للمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أين يحرم من أتى من الكويت إلى المدينة ويريد العمرة.mp3","categories":["المواقيت","الإحرام"]},{"id":2719,"question":"كثير من الإخوة القادمين من خارج المملكة يأتي لأداء العمرة ويقول: أريد أن آخذ عن والدي أو والدتي عمرة، فيقول من أين أحرم؟ من التنعيم أو من الميقات؟","title":"من أين يُحْرِم الوافِد يريدُ عمرةً أخرى؟","answer":"الجواب: من الحِلّ، التنعيم، أو غيره من الحل، عرفات أو التنعيم أو الجعرانة؛ لأنه قد دخل بإحرام شرعي من الميقات، مثل ما أحرمت عائشة من التنعيم؛ لأنها قد دخلت بإحرامها الأول من الميقات. صار من أهل مكة، حكمه حكم أهل مكة، يحرمون من الداخل، يعني من خارج الحرم، لكن ما يلزم يرجع للميقات، من عرفات من الجعرانة من التنعيم، يسمونه العمرة الآن.","link":"https://binbaz.org.sa/fatwas/22862/من-اين-يحرم-الوافد-يريد-عمرة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يأتي من خارج المملكة ويريد العمرة عن والديه فمن أين يحرم.mp3","categories":["المواقيت","الإحرام"]},{"id":3640,"question":"(الاشتراط) مقيّد بالخوف؟","title":"هل الاشتراط في الحج مقيّد بالخوف؟","answer":"الجواب: نعم؛ يخاف؛ إما مريض وإلا حرب.\nس: وإن اشترط من غير خوف هل ينفعه الشرط؟\nالشيخ: الظاهر العموم، مثل المرأة التي تخاف الحيض وأشباهه.","link":"https://binbaz.org.sa/fatwas/23825/هل-الاشتراط-في-الحج-مقيد-بالخوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/محلي حيث حبستني.. هل الاشتراط في الحج مقيد بالخوف.mp3","categories":["المواقيت","الإحرام"]},{"id":4641,"question":"يُؤخذ من هذا الحديث - حجّ عن نفسك، ثم حجّ عن شبرمة- تغيير النية بعد عقد نية الإحرام؟","title":"حكم تغيير النية بعد عقد نية الإحرام","answer":"الجواب: تقع عن نفسه.\nس: بعد عقد النية؟\nج: نعم، يكون عن نفسه، ينعقد عن نفسه، لا عن الشخص الذي أراد الحجَّ عنه؛ لأنه مأمورٌ أن يحجَّ عن نفسه قبل أن يحجَّ عن غيره.","link":"https://binbaz.org.sa/fatwas/24931/حكم-تغيير-النية-بعد-عقد-نية-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تغيير النية بعد عقد نية الإحرام.mp3","categories":["المواقيت","الإحرام"]},{"id":4642,"question":"الصبي يُلبي عنه وليُّه؟","title":"ما حكم إحرام وتلبية الصبي بالحج؟","answer":"الجواب: دون السبع يُلبي عنه وليُّه.\nس: بعد السبع يختلفون الصبيان في التَّمييز؟\nج: يُعلَّم إذا بلغ السبع، هذا محل الأمر بالصلاة والعبادة، يُعلَّم، وإذا ما لبَّى الأمر سهل، التلبية سنة، كذلك يلبس الإحرام.\n... يلبس، لا يحطّ عليه قميصًا ولا شيئًا.\nس: قال أبو حنيفة: لا يصح إحرامه ولا يلزمه شيء من محظورات الإحرام وإنما يحج به على جهة التدريب، هل هذا القول صحيح؟\nج: ليس بشيءٍ، أحاديث النبي ﷺ واضحة.","link":"https://binbaz.org.sa/fatwas/24932/ما-حكم-احرام-وتلبية-الصبي-بالحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إحرام وتلبية الصبي للحج.mp3","categories":["المواقيت","الإحرام"]},{"id":4643,"question":"لو أتى مكة ولم يكن اعتمر عمرةَ الإسلام ألا يلزمه الإحرام؟","title":"حكم من أتى مكة ولم يكن اعتمر عمرةَ الإسلام","answer":"الجواب: نعم يلزمه من الحلِّ، إذا كان أتاها ما نوى عمرةً؛ يُحرم من الحلِّ.","link":"https://binbaz.org.sa/fatwas/24933/حكم-من-اتى-مكة-ولم-يكن-اعتمر-عمرة-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يلزم الإحرام من أتى مكة ولم يكن اعتمر عمرةَ الإسلام.mp3","categories":["المواقيت","الإحرام"]},{"id":4644,"question":"مَن ذهب إلى جدة لعملٍ وهو ناوٍ العمرة؟","title":"إحرام مَن ذهب إلى جدة لعملٍ وهو ناوٍ العمرة","answer":"الجواب: يرجع إلى الميقات الذي مرَّ عليه، إن كان جاء من نجدٍ أو من الطائف لجدة لعملٍ وهو ناوٍ لعمرة يرجع إلى الميقات ويُحرم منه.  أما إذا ما نوى، جاء لحاجةٍ ثم طلع عليه في جدة قال: ما دام أني وصلتُ هذا المحلّ أود أن آخذ عمرةً، فيُحرم من مكانه.","link":"https://binbaz.org.sa/fatwas/24934/احرام-من-ذهب-الى-جدة-لعمل-وهو-ناو-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مَن ذهب إلى جدة لعملٍ وهو ناوٍ العمرة، فمن أين يحرم.mp3","categories":["المواقيت","الإحرام"]},{"id":4647,"question":"كراهة الإحرام بالحج قبل أشهر الحج للتنزيه؟","title":"ما حكم الإحرام بالحج قبل أشهر الحج؟","answer":"الجواب: الأقرب والله أعلم هو هذا؛ لأنها من السنة، ما قال: لا تفعلوا، قال: من السنة، يعني سنة النبي ﷺ.\nس: لكن تجاوز تحديد أشهر الحجّ؟\nج: الأقرب والله أعلم أنه للكراهة، إذا أحرم بالحجِّ قبل وقت الحجِّ يكون للكراهة، ويجعلها عمرةً، وهكذا لو أحرم بالحجِّ أو العمرة قبل الميقات يلزمه، وقد فعل ما لا ينبغي.\nس: يلزمه لكن هل يأثم؟\nج: الله أعلم، الأقرب عدم الإثم، وخالف السنة.","link":"https://binbaz.org.sa/fatwas/24937/ما-حكم-الاحرام-بالحج-قبل-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإحرام بالحج قبل أشهر الحج.mp3","categories":["المواقيت","الإحرام"]},{"id":4652,"question":"صلاة ركعتين للإحرام لها أصل؟","title":"ما حكم صلاة ركعتين للإحرام؟","answer":"الجواب: ... عموم حديث: إنه أتاني آتٍ من ربي فقال: صلِّ في هذا الوادي، النبي صلَّى فيه، صلَّى الظهر وأحرم وركب في حجة الوداع، فإذا وافق فريضةً كفت الفريضة، وأما إذا كان ما هو بوقت فريضةٍ وتوضَّأ فسنة الوضوء تكفي؛ أخذًا بالعموم: صلِّ في هذا الوادي المبارك.","link":"https://binbaz.org.sa/fatwas/24942/ما-حكم-صلاة-ركعتين-للاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لصلاة ركعتين للإحرام أصل.mp3","categories":["الإحرام","صلاة التطوع"]},{"id":4653,"question":"هل ثبت في الغسل شيء غير أمر الحائض والنُّفساء؟","title":"ما دليل استحباب الغسل للمحرم؟","answer":"الجواب: حديث: \"تجرد لإهلاله واغتسل\"، حديث زيدٍ، وحديث ابن عمر: \"من السنة أن يغتسل\"، وفي حديث: أنَّ الحائض والنُّفساء اغتسلتا، وفي حديث جابرٍ: أنَّ أسماء بنت عميس ولدت محمد بن أبي بكر في ذي الحليفة، فأمرها النبيُّ أن تغتسل، وهكذا عائشة أمرها أن تغتسل، فإذا كانت الحائض تغتسل والنُّفساء وهما لا صلاةَ عليهما، ولا طهارةَ لهما، فغيرهما من باب أولى.","link":"https://binbaz.org.sa/fatwas/24943/ما-دليل-استحباب-الغسل-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت في الغسل شيء غير أمر الحائض والنُّفساء.mp3","categories":["المواقيت","الإحرام"]},{"id":4657,"question":"الذي لا يخاف مرضًا ما يشترط؟","title":"هل يشترط من لا يخاف مرضًا في الحج؟","answer":"الجواب: الأفضل عدم الاشتراط؛ لأنَّ الرسول لم يشترط عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24948/هل-يشترط-من-لا-يخاف-مرضا-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط من لا يخاف مرضًا أو غيره في الحج.mp3","categories":["المواقيت","الإحرام"]},{"id":4663,"question":"مَن أتى بالحجِّ مُفردًا، وأراد عمرةً بعد الحجِّ، يأتي بها من التنعيم أم من المواقيت؟","title":"ما حكم من أتى بالحجِّ مُفردًا وأراد عمرةً بعده؟","answer":"الجواب: من التنعيم مثلما فعلت عائشةُ ويكفي، يعني من الحلِّ.","link":"https://binbaz.org.sa/fatwas/24955/ما-حكم-من-اتى-بالحج-مفردا-واراد-عمرة-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أتى بالحجِّ مُفردًا، وأراد عمرةً بعد الحجِّ.mp3","categories":["المواقيت","الإحرام"]},{"id":4672,"question":"المرأة التي تخاف على نفسها العادة هل تشترط عند إحرامها؟","title":"هل تشترط المرأة عند إحرامها إن خافت العادة؟","answer":"الجواب: ما أعلم مانعًا، أما في الحجِّ لا؛ لأنها تنتظر؛ لأنَّ الحجَّ لا بد من الطواف فيه. الحيض محل نظر.. ، لكن ليس ببعيدٍ؛ لأنه قد يُعطلها كثيرًا.  قد يُقال بالحج أيضًا إذا كانت جاءت مُتأخرةً أو متقدمةً، يمديها تطهر، لكن قد تأتي متأخرةً وتخشى من التَّعطيل، وتفوت عليها أشياء، المقصود إذا دعت حاجةٌ إلى الاشتراط لا بأس، الأصل الجواز، النبي قال لضباعة وهي مريضة: حُجِّي واشترطي.","link":"https://binbaz.org.sa/fatwas/24964/هل-تشترط-المراة-عند-احرامها-ان-خافت-العادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تشترط المرأة عند إحرامها إن خافت على نفسها العادة.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":5215,"question":"يقول السائل: هل يجوز لي أن أتمتع في اليوم الثامن؟","title":"هل يجوز للحاج التمتُّع في اليوم الثامن؟","answer":"الجواب: نعم، إذا دخلت البلد، وجئتَ من بلدك الثامن وأنت مُلبٍّ بالعمرة؛ تطوف وتسعى، وإن كنتَ مُلبيًا بالحج تجعلها عمرةً، تنويها عمرة، فتطوف وتسعى وتُقصّر وتحلّ كما أمر النبيُّ أصحابَه، ثم تُلبي وتغتسل بعد ذلك، تستريح وتغتسل وتتطيَّب، ثم تُلبي بالحج، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/30159/هل-يجوز-للحاج-التمتع-في-اليوم-الثامن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 191.mp3","categories":["المواقيت","الإحرام"]},{"id":5227,"question":"هذا سائل يقول: إنَّ بعضًا من طلبة العلم يقولون: إنَّ مَن أحرم بحجةٍ أو عمرةٍ قبل الميقات فإن ذلك الإحرام لا ينعقد، وعليه فيكون قولهم قطعًا بعدم انعقاد الإحرام تبعًا لابن حزم، فماذا نقول لهؤلاء ونرد عليهم به؟ جزاكم الله خيرًا.","title":"ما حكم من أحرم بحجةٍ أو عمرةٍ قبل الميقات؟","answer":"الجواب: الصواب الذي عليه جمهورُ أهل العلم أنه ينعقد، ولكن ترك الأفضل، فالنبي ﷺ لما وقَّت المواقيت قال: هُنَّ لهُنَّ، ولمَن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحجَّ أو العمرة فالسُّنة له أن يُحرم من الميقات، فلو أحرم من غير الميقات انعقد عند أهل العلم، ولكنه ترك الأفضل، فلو أحرم صاحبُ الطائف من بيته، أو صاحبُ المدينة من بيته، أو صاحبُ الرياض من بيته؛ أجزأ، ولكن ترك ما هو السنة، وهو ألا يُحرم إلا من الميقات، وقصاراه أنه شدَّد على نفسه، والله جلَّ وعلا يسَّر له الأمر، وجعل الإحرام من الميقات حتى يكون هذا أيسر عليه، وحتى لا تطول عليه المدَّة في الإحرام، فإذا شدد على نفسه وأحرم قبل ذلك -إمَّا جهلًا وإمَّا لقصدٍ آخر- فإنَّ إحرامه ينعقد، وقصاراه أنه فعل مكروهًا، أو ترك ما هو الأفضل، وأما القول بأنه لا ينعقد فهو قولٌ ضعيفٌ وليس بشيءٍ.","link":"https://binbaz.org.sa/fatwas/30171/ما-حكم-من-احرم-بحجة-او-عمرة-قبل-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 261.mp3","categories":["المواقيت","الإحرام"]},{"id":5250,"question":"هل يقع من أهل مكة تمتع وقران؟","title":"ما حكم حج التمتع والقران لأهل مكة؟","answer":"الجواب: نعم، لا بأس، لكن ليس عليهم هَدْي التمتع والقران، فلهم أن يمتعوا بالعمرة في أشهر الحج، ولهم أن يقرنوا بينهما، لكن الأفضل لهم الحج المفرد؛ لأنَّ الله وسَّع لهم العمرة، متى شاءوا اعتمروا، فلو اعتمروا في أشهر الحج فلا بأس.","link":"https://binbaz.org.sa/fatwas/30665/ما-حكم-حج-التمتع-والقران-لاهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 737.mp3","categories":["المواقيت","الإحرام"]},{"id":5270,"question":"رجل أحرم من الميقات وهو لابس المخيط، لما وصل إلى مكة مرض ورجع إلى بلاده غير معتمر، في هذه الحال ماذا عليه؟","title":"حكم من أحرم من الميقات ورجع لبلده ولم يعتمر","answer":"الجواب: لابس المخيط، ما عنده إحرام؟ س: ما عنده إحرام أو أنه تكاسل؟ ج: المقصود عليه فدية، عليه إطعام ستة مساكين، أو صوم ثلاثة أيام، أو ذبح شاة، أحد الثلاثة في لبس المخيط مثلما عليه لو حلق رأسه، أما إذا رجع ولم يحل إحرامه عليه أن يرجع إلى مكة. س: ما اعتمر، أحسن الله إليك؟ الشيخ: ما أحرم تقول؟ س: هو أحرم لكن مرض ورجع؟ الشيخ: إن كان عمل عمل المحصر لا بأس، إن كان نحر وقصر وحلّ على أنه محصر لا بأس؛ لأن مرضه يكون إحصارًا فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] إذا أحصر الإنسان بالمرض أو بالعدو أو بذهاب النفقة يكون محصرا، والمحصر ينحر شاة، أو سُبع بدنة، أو سُبع بقرة بنية الإحصار، ثم يحلق رأسه أو يقصر ويحل، والحمد لله؛ لأن الله قال: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] إذا لم يشترط، وإذا اشترط ما عليه شيء. س: إذا كان ما اشترط يا شيخ؟ ج: عليه أن يعمل عمل الإحصار، يهدي ثم يقصر ويحلق. س: حتى وإن وصل إلى الرياض يقصر شعره في الرياض؟ ج: نعم نعم، في محله الذي وصل فيه.[1]","link":"https://binbaz.org.sa/fatwas/30877/حكم-من-احرم-من-الميقات-ورجع-لبلده-ولم-يعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 013.mp3","categories":["المواقيت","الإحرام"]},{"id":5340,"question":"إذا كانت المرأة عليها الدورة الشهرية وتريد العمرة وهي خارج مكة هل تستطيع أن تحرم من الميقات ومن ثم تطوف إذا طهرت؟","title":"حكم إحرام الحائض من الميقات وطوافها إذا طَهُرت","answer":"الجواب: نعم، تُحْرِم ولو هي في الحيض، تُحْرِم من الميقات وإذا طَهُرت تطوف وتسعى، تبقى في بيتها حتى تَطهُر، وإذا طَهُرت اغتسلت وطافت، والحمد لله، وهكذا النفساء، إذا أحرمت وهي نفساء وبقيت على إحرامها حتى طهرت كذلك.[1]","link":"https://binbaz.org.sa/fatwas/31013/حكم-احرام-الحاىض-من-الميقات-وطوافها-اذا-طهرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 061.mp3","categories":["المواقيت","الإحرام"]},{"id":5361,"question":"رجل نوى العمرةَ ثم أحرم من الميقات، وبعد دخول الحرم وجد الزِّحام فرجع إلى منزله ولبس ملابسه ولم يعتمر في رمضان الماضي، ماذا عليه الآن، علمًا بأنه غير مُتزوج؟","title":"ما حكم من أحرم ولم يعتمر بسبب الزحام؟","answer":"الجواب: عليه أن يُكمل العمرة، ما زال مُحرمًا، وعليه أن يذهب فيطوف ويسعى ويُقصر ويحلّ، وإذا كان جاهلًا ما عليه شيء من جهة لبس الثياب؛ من أجل جهله.[1]","link":"https://binbaz.org.sa/fatwas/31065/ما-حكم-من-احرم-ولم-يعتمر-بسبب-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima004.mp3","categories":["المواقيت","الإحرام"]},{"id":6117,"question":"إذا أحرم رجل بالعمرة، وقصده التمتع، ثم خرج بعد العمرة إلى جدة، أو خارج الميقات، فهل يعتبر متمتعًا إذا رجع، وكمل حجه؟","title":"حكم من أحرم متمتعاً وخرج إلى جدة أو غيرها","answer":"الجواب: الصواب أنه لا يخرج بهذا عن التمتع، إذا دخل مكة متمتعًا بعد رمضان، محرمًا بالعمرة، وقصده الحج، ثم بعد الفراغ من العمرة خرج إلى الطائف، أو إلى جدة لبعض الحاجات، فالصواب أنه يبقى على تمتعه. وقال بعض أهل العلم: إنه  إذا خرج ... ورجع بالحج محرمًا؛ فإنه يكون بذلك قد نقض تمتعه، ويكون مفردًا إذا رجع من الميقات مسافة القصر من... مثلًا، أو من غيره من المواقيت ... بالحج صار مفردًا، هذا قاله جماعة من أهل العلم. والأقرب، إن شاء الله. والأظهر: أنه بهذه التصرفات بين الحج، والعمرة لا يكون مفردًا، بل يبقى على تمتعه إلا إذا رجع إلى بلاده، إذا رجع إلى بلاده، ثم جاء بحج مفردًا؛ فإنه يكون مفردًا، ولا دم عليه يروى هذا عن عمر، وابنه -رضي الله عنهما- وهو قول عامة أهل العلم.","link":"https://binbaz.org.sa/fatwas/1536/حكم-من-احرم-متمتعا-وخرج-الى-جدة-او-غيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_466.mp3","categories":["الإحرام"]},{"id":6180,"question":"نويت الحج، أو العمرة، وتحركت من الرياض في أيام الحج، وأراد الذهاب إلى جدة لمهمة عمل، فمن أين أحرم؟","title":"حكم من قصد الحج أو العمرة وتعدى الميقات ولم يحرم","answer":"الجواب: إذا كان الإنسان أراد الحج، أو العمرة، وذهب إلى جهة مكة؛ فعليه الإحرام من الميقات الذي يمر عليه، إن كان من الرياض، أو الطائف، أو ما دونهما، أو ما هو غير ذلك يمر على ميقات أهل نجد، ويحل منه، وهو السيل المعروف، وهذا المحرم المعروف يحرم من أحدهما. فإن كان من جهة أخرى كما جاء من طريق المدينة؛ يحرم من ميقات المدينة، أو جاء من طريق اليمن؛ يحرم من ميقات اليمن يلملم، أو جاء من طريق الشام، أو من مصر جاء من طريق البحر؛ يحرم من ميقات مصر، والشام، رابغ الجحفة، أو جاء من طريق العراق؛ يحرم من طريق العراق، وهو ... المعروفة، أو من  السيل ميقات أهل نجد كما هو معروف الآن.  أما من جاء إلى جدة ما عنده نية عمرة، جاء إلى جدة لعمل، ثم طرأ عليه أن يعتمر؛ يحرم من جدة من مكانه ، فإن النبي -عليه الصلاة والسلام- قال: لما وقت المواقيت قال: هن لهن، ولمن أتى عليهن من غير أهلهن، ممن أراد الحج، والعمرة، وكان دون ذلك أي دون المواقيت فمهله من حيث أنشأ حتى أهل مكة من مكة.  فإذا جاء جدة، ما قصد العمرة، جاء إليها لعمل، ثم بدا له أن يعتمر، يحرم من جدة، أو بدا له أن يحج، يحرم من جدة، أما إذا جاء من الرياض، أو جاء من اليمن، أو جاء من أي مكان ... المواقيت قصده الحج، أو قصده العمرة، أو قصده يمر جدة، ويعتمر فهذا يحرم من الميقات إن كان من طريق المدينة، فمن ميقات المدينة، إذا كان من طريق الطائف فمن ميقات الطائف.. جاء من طريق اليمن يحرم من يلملم.\n...... أسئلة...","link":"https://binbaz.org.sa/fatwas/1639/حكم-من-قصد-الحج-او-العمرة-وتعدى-الميقات-ولم-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_530.mp3","categories":["الإحرام","المواقيت"]},{"id":6182,"question":"كيف يحرم في الطائرة؟","title":"كيفية إحرام من كان على الطائرة أو السفينة","answer":"الجواب: في الطائرة يحرم في الجو نعم، وهكذا في البحر، إذا وازى المواقيت، تحرم من البحر في الباخرة، أو السفينة، وإذا كان في الجو يتحرى الميقات، ويحرم قبل أن يصله، أو يحرم في مطار من بلده إذا كان يخشى أن يلتبس عليه الأمر لا بأس إذا تقدم بإحرامه لحاجة لا بأس. ولكن في الغالب أنه يتيسر له أن يستعد في بلاده، يغتسل إذا تيسر، يتطيب، يلبس الإزار، والرداء، ويكون في الطائرة مستعدًا فإذا صار بينه وبين جدة نحو نصف ساعة؛ يحرم؛ لأنه حينئذ قد وزاى الميقات إذا كان من طريق الطائرة. أما إذا كان من طريق المدينة معروف أتى أهل المدينة أحرم، وإذا كان من طريق البحر من طريق الساحل إذا وازى رابغ، أو من طريق مصر، أو الشام، أحرم وهو في الجو، أو قبله بيسير حتى يحتاط، ويحرم قبل ذلك، فإنه حين يقوم من المطار، ويمشي قليلًا تسير الطائرة قليلًا يحرم احتياطًا لا بأس، أما تأجيل الإحرام إلى أن يأتي جدة لا.","link":"https://binbaz.org.sa/fatwas/1640/كيفية-احرام-من-كان-على-الطاىرة-او-السفينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_531.mp3","categories":["المواقيت","الإحرام"]},{"id":6539,"question":"ذهبت إلى العمرة، واعتمرت من جدة، فهل هناك علي هدي؟","title":"حكم من أحرم للعمرة من جدة","answer":"الجواب: إذا كنت من أهل جدة يكفي، أما إذا كنت جئت من مكان آخر، من الرياض، أو من الطائف، وأنت تقصد العمرة، ولكن ما أحرمت إلا من جدة، وتجاوزت الميقات؛ فعليك دم عن ترك الميقات، إذا كنت جئت من مكان بعيد عن جدة، مثلًا جئت من الطائف، أو جئت من رابغ، وأنت من أهل رابغ، وما أحرمت من رابغ، وجئت العمرة، وأنت في رابغ، ولا أحرمت منه، يكون عليك ذبيحة تتميمًا لعمرتك، وجبرًا لها.  أما إذا كنت من أهل جدة؛ فلا بأس، أو كنت جئت جدة ما نويت شيئًا، سافرت من الرياض، أو من المدينة، أو من غيرها إلى جدة، ما عندك نية، ما عندك نية عمرة، ما طرأ عليك عمرة، فلما صرت في جدة؛ طرأ عليك أخيرًا، وبدا لك أخيرًا أن تعتمر؛ فلا بأس تحرم من جدة، ولا شيء عليك؛ لأنك ما نويت العمرة إلا منها؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2376/حكم-من-احرم-للعمرة-من-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_910.mp3","categories":["المواقيت","الإحرام"]},{"id":6675,"question":"مسافر أقام في الرياض، ونوى العمرة، وأحرم من جدة، فما حكم الإسلام؟","title":"حكم من نوى العمرة وجاوز الميقات ولم يحرم","answer":"الجواب: إذا توجه من الرياض إلى جدة للعمرة يحرم من الميقات هذا الواجب، إذا جاء ميقات ... أو قبله بيسير يتحرى، ويحرم، يستعد لهذا في بيته، يلبس الإزار، والرداء ، يتطيب لا بأس، أو  في الطائرة يتطيب، فكل ذلك جائز، لكن الإحرام هو أن ينوي الدخول في العمرة، أو يلبي، هذا عند قرب الميقات وعند ... الميقات يلبي، ويقول: اللهم لبيك عمرةن وينوي بقلبه، هذا هو المشروع، هذا الواجب، ولا يترك حتى يأتي جدة لا، وإذا فعل؛ فعليه دم إذا لم يحرم إلا من جدة، وهو جاء من الرياض، أو من غير الرياض من جهة الشرق، ومر على الميقات، ولم يحرم؛ يكون عليه دم، أو جاء من المدينة ولم يحرم إلا من جدة وهو قاصد العمرة، أو الحج؛ يكون عليه دم. السؤال: إذا كان جاء للعمل يريد عملًا، وأراد أن ينتهز الفرصة للعمرة؟ الجواب: بعد عمله ؟ ما أراده الآن؟ السؤال: نعم؟ الجواب: إذا أرادها بعد العمل ما في بأس ، إذا كان عمله في جدة، وينوي إذا فرغ من العمل أن يعتمر؛ لا بأس، أما أنه ينوي في الرياض أنه يعتمر فهذا لا بد يحرم من الميقات.  السؤال: لكن إذا كان يبغى إنه يروح جدة، ثم يحرم من الميقات جائز هذا؟ الجواب: ما في بأس.. ثم  يعود للميقات.","link":"https://binbaz.org.sa/fatwas/2553/حكم-من-نوى-العمرة-وجاوز-الميقات-ولم-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1048.mp3","categories":["المواقيت","الإحرام"]},{"id":7240,"question":"شخص سافر أيام الحج من الرياض إلى المدينة المنورة، وليس هو محرم، ثم سافر من المدينة إلى جدة، ومكث فيها خمسة عشر يومًا وهو مسافر بالطائرة من مكان سكنه بالرياض، ولم يكن قصده الحج، ولكن للزيارة، ولما حضرت أيام الحج؛ أراد أن يحج، وحج، وكمل حجه، فهل يلزمه الهدي؛ لأنه من سكان الرياض، وأحرم من ميقات جدة، وهل جدة من المواقيت؟","title":"حكم من جاء إلى جدة للزيارة ثم أحرم منها للحج","answer":"الجواب:\n\nلا ما يلزمه شيء ما دام جاء إلى جدة ما قصد حجًا ولا عمرة، جاء للزيارة ثم صادف الحج، وأحرم من جدة بالحج فقط بدون عمرة؛ ما عليه فدية.\n\nأما إذا أحرم بالعمرة من جدة، وتمم العمرة، ثم أحرم بالحج، أو أحرم بهما جميعًا من جدة؛ فعليه الهدي؛ لأنه متمتع، أما إذا أحرم بالحج مفردًا من جدة، صادف الحج وهو فيها، وأحرم منها؛ فلا بأس عليه، يكون مفردًا.","link":"https://binbaz.org.sa/fatwas/3293/حكم-من-جاء-الى-جدة-للزيارة-ثم-احرم-منها-للحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1618.mp3","categories":["المواقيت","الإحرام"]},{"id":7481,"question":"أيضاً تسأل عن حديث الرسول ﷺ، تقول: ما معنى حديث ضباعة بنت الزبير أنها قالت: يا رسول الله! إني أريد الحج وأنا شاكية، فقال لها النبي ﷺ: حجي واشترطي أن محلي حيث حبستني هل هذا الأمر واجب أم سنة؟","title":"سنية الاشتراط في الحج للخائف أو المريض وغيرهما","answer":"الجواب: لمعروف عند العلماء أنه سنة، يشترط الإنسان إذا خاف من حوادث مثل: مريض، أو خوف، يشترط ويقول عند الإحرام: فإن حبسني حابس فمحلي حيث حبستني، فالذي أحصر مثلاً: بخراب السيارة، أو بغير ذلك، إذا كان قد اشترط فلا شيء عليه، يتحلل ولا شيء عليه. مثل المسألة الأولى الذي مثلاً عند الإحرام قال: فإن حبسني حابس فمحلي حيث حبستني، يتحلل ولا شيء عليه، بسبب خراب السيارة وتعطله، أو مرض أصابه، أو عدو منعه، ..................حديث ضباعة بنت الزبير سواء سواء. نعم","link":"https://binbaz.org.sa/fatwas/4326/سنية-الاشتراط-في-الحج-للخاىف-او-المريض-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_004/00406.mp3","categories":["الإحرام"]},{"id":7482,"question":"سماحة الشيخ! هذه الرسالة وصلت من محمد مسرور الحويرث وعائلته، الرياض، أيضاً هناك رسالتان قريبتان من هذه الرسالة؛ واحدة من شافية مطير الغزواني وواحدة من سلطان محمد السلطان، عمان، يقول: وصلت إلى الميقات ومعي عائلتي، وكلنا أحرمنا، وكنت كبيرهم وأعرفهم بمناسك الحج، ولبيت وقد لبوا بتلبيتي وقد نسيت وقلت: لبيك اللهم لبيك.. إلى آخره، لبيك عمرة متمتعاً بها إلى الحج، ونحن نريد عمرة في رمضان فقط، ولما وصلنا إلى البيت الحرام قال بعض أفراد العائلة: لماذا ذكرت الحج في التلبية ونحن لا نريد حجاً؟! عند ذلك تذكرت، أرجو إفادتنا، هل يلزمنا البقاء في مكة إلى أن نحج، أو يلزمنا دم ونرجع إلى أهلنا؟","title":"حكم من أحرم في رمضان بعمرة متمتعاً بها إلى الحج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفهذا السؤال وهو إحرام الإخوان المذكورين من الميقات في رمضان في تلبيتهم بالعمرة متمتعين بها إلى الحج، هذا السؤال لا يلزمك أيها السائل الجلوس في مكة إلى الحج، ولا يلزمك دماً بل العمرة في رمضان لا توصف بأنها تمتع إلى الحج. وقولك في التلبية: متمتعاً إلى الحج، لا يضر ولا يؤثر شيئاً، إنما هذا يكون بعد رمضان لمن أراد الجلوس والحج بعد ذلك، وأما من لم يرد ذلك فإنه لا يقولها بل يقول: لبيك عمرة حتى ولو كان أراد الجلوس إلى الحج، ليس من اللازم أن يقول: متمتعاً بها إلى الحج، يكفي النية في قلبه، ثم لو قال ذلك: لبيك عمرة متمتعاً بها إلى الحج، وأراد ألا يحج فلا يلزمه البقاء إلى الحج، ليس بلازم، فإنه قد ينوي ثم يطرأ عليه شيء آخر يمنعه من ذلك، فلا حرج عليه.\nوبكل حال: فأنت أيها الأخ ومن معك من الرفقة الذين لبوا جميعاً على تلبيتك بعمرة متمتعاً بها إلى الحج لا يضرهم ذلك، ولا بأس عليهم، ولا يلزمهم الجلوس حتى يحجوا، وليس عليهم فدية، والحمد لله","link":"https://binbaz.org.sa/fatwas/4327/حكم-من-احرم-في-رمضان-بعمرة-متمتعا-بها-الى-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00501.mp3","categories":["الإحرام"]},{"id":7537,"question":"هذه الرسالة من المستمع محمد صالح زروي من ينبع البحر، يقول: كيف يفعل الحاج إذا احتلم وهو محرم وهو في فعل الحج، وبأن الكعبة لا يطوف بها أحد وهو جنب؟","title":"حكم المحرم إذا احتلم","answer":"الجواب: إذا احتلم وهو محرم يغتسل غسل الجنابة ولا شيء عليه؛ لأنه لم يتعمد هذا، هذا ليس باختياره، مثل الصائم في رمضان يحتلم في النهار يغتسل ولا شيء عليه، صومه صحيح وحجه صحيح، فإذا احتلم في عرفات أو في مزدلفة، أو في الطريق بعدما أحرم، كل ذلك لا حرج عليه، ولكن يلزمه الغسل، فإن لم يجد ماءً؛ لأنه في محل ما فيه ماء، أو كان مريضاً لا يستطيع استعمال الماء، استعمل التيمم التعفر بالتراب، فيأخذ التراب بيديه بنية الجنابة فيمسح وجهه وكفيه بنية الجنابة ويطهر بذلك، ولا شيء عليه وحجه صحيح تام؛ لأن هذا الاحتلام ليس باختياره، والله لا يكلف نفساً إلا وسعها سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/4523/حكم-المحرم-اذا-احتلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01107.mp3","categories":["الإحرام"]},{"id":7547,"question":"هذه الرسالة من زين الدين علي بسام الرياض، يقول: هل يجوز أن يتحول المسلم من نسك إلى نسك آخر، وما هي أفضل الأنساك في الحج؟","title":"التحول من نسك لآخر في الحج","answer":"الجواب: هذا السؤال فيه تفصيل: إن كان أحرم بالعمرة فله أن يتحول إلى القران، يحرم بالحج مع العمرة يكون قارناً، إذا كان معه الهدي، فإن كان ما معه هدي، لا إبل ولا بقر ولا غنم، فالأفضل أن لا يتحول، بل يبقى على حاله معتمراً، فإذا طاف وسعى وقصر حل، أما إن كان معه هدي، كبعير، أو بقرة، أو شاة، أو أكثر، فإن السنة أن يحرم بحج؛ لأن الرسول صلى الله عليه وسلم أمر بذلك، قال عليه السلام: من كان معه هدي فليحل بحج مع عمرته، ولا يحل منهما حتى يحل منهما جميعاً.\nالمقدم: يعني يكون قارناً؟\nالشيخ: يعني إذا أحرم بالعمرة وحدها، ثم أحب أن ..... الحج إذا كان معه الهدي، فهذا هو السنة، يلبي بالحج مع العمرة ويكون قارناً بعد ذلك، أما إذا أحرم بالحج وحده، فليس له فعل شيء بل يبقى على حاله حتى يجعلها عمرة، إما يستمر إلى الحج، وإما يفسخ العمرة، يطوف ويسعى ويقصر ويجعلها عمرة، كما أمر النبي ﷺ أصحابه الذين أحرموا بالحج وليس معهم هدي أن يجعلوا عمرة .\nفالحاصل أن له أحوالاً:\nأحدها: أن يحرم بالحج وحده، ليس معه عمرة، فهذا إن كان وقت حج قريب كمل حجه والحمد لله، فإن كان وقت الحج ليس بقريب بأن عنده وقت، فالأفضل يجعلها عمرة، يفسخ، يعني: ينويها عمرة، يطوف ويسعى ويقصر ويجعلها عمرة، كما أمر النبي أصحابه بذلك عليه الصلاة والسلام.\nالحال الثاني: يحرم بالعمرة وحدها، فهذا له أن يجعلها قراناً إذا كان في أشهر الحج، إذا كان بعد رمضان، له أن يلبي بالحج مع العمرة، يصير قارن، ولا سيما إذا كان معه هدي فإنه يلبي بالحج كما أمر بذلك، ويكون قارناً بذلك، فلا يحل حتى يحل منهما جميعاً يوم النحر، وإن بقي على إحرامه معتمراً فهو أفضل حتى يكمل عمرته، إلا إذا كان معه هدي فإنه يلبي بالحج مع العمرة، ويبقى على إحرامه حتى يحل منهما جميعاً يوم النحر.\nأما الذي أحرم بالعمرة وليس معه هدي، فهذا الأفضل أنه لا يلبي بحج مع عمرته، بل يبقى على إحرامه بالعمرة حتى يكملها بالطواف والسعي والتقصير. نعم.","link":"https://binbaz.org.sa/fatwas/4534/التحول-من-نسك-لاخر-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01206.mp3","categories":["الإحرام"]},{"id":7809,"question":"يقول هذا السائل يا سماحة الشيخ: أديت العمرة وأنا من السودان ولكنني أحرمت من رابغ هل هذا صحيح؟","title":"مشروعية إحرام المعتمر من أول ميقات يحاذيه","answer":"الجواب: الواجب عليك الإحرام من ميقات السودان، إن كنت جئت من طريق المدينة من ميقات المدينة، أو جئت من طريق البحر تحرم من الميقات أول ميقات يمر عليك وهو الجحفة رابغ، هذا هو الواجب عليك أول ميقات تحاذيه تحرم منه. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/5203/مشروعية-احرام-المعتمر-من-اول-ميقات-يحاذيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05121.mp3","categories":["الإحرام"]},{"id":7829,"question":"يقول هذا السائل يا سماحة الشيخ: أديت العمرة وأنا من السودان ولكنني أحرمت من رابغ هل هذا صحيح؟","title":"مشروعية إحرام المعتمر من أول ميقات يحاذيه","answer":"الجواب: الواجب عليك الإحرام من ميقات السودان، إن كنت جئت من طريق المدينة من ميقات المدينة، أو جئت من طريق البحر تحرم من الميقات أول ميقات يمر عليك وهو الجحفة رابغ، هذا هو الواجب عليك أول ميقات تحاذيه تحرم منه. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/5203/مشروعية-احرام-المعتمر-من-اول-ميقات-يحاذيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05121.mp3","categories":["الإحرام"]},{"id":8112,"question":"الرسالة الأخيرة التي بين يدينا في لقائنا هذا وردتنا من المواطن عبد الله علي سليمان الأسمري من بني أسمر من تهامة وادي الغيل، يقول في رسالته: حاجاً متمتعاً، ماذا يقول عند التلبية وقت إحرامه؟ وماذا يفعله أثناء حجه؟","title":"صفة تلبية المتمتع وقت الإحرام","answer":"الجواب: مثل غيره، عند التلبية يقول: لبيك عمرة وحج عند التلبية في الميقات، بعدما يغتسل إذا تيسر الغسل، بعد ذلك، وبعد ما يلبس ملابس الإحرام الإزار والرداء يقول: اللهم لبيك عمرة وحجا، أو يقول: اللهم لبيك عمرة، ثم يقول: اللهم لبيك حجاً، ولو بعدها أوقتها بوقت ساعة ساعتين أكثر أقل قبل الطواف، قبل أن يطوف، ولو في أثناء الطريق تلبي بالعمرة أولاً ثم يلبي بالحج في أثناء الطريق قبل الطواف، أو يلبي بهما جميعاً في الميقات: اللهم لبيك عمرة وحجاً هذه سنة الإحرام بالتمتع، بعدما يفعل ما شرعه الله من الاغتسال، والطيب، ولبس الإزار والرداء في الميقات، أو قبل الميقات يتأهب، فإذا جاء الميقات لبى بقوله: اللهم لبيك عمرة وحجاً، أو يقول: اللهم لبيك عمرة، ثم في أثناء الطريق يلبي بالحج كل هذا لا بأس به، كل هذا يسمى: إحراماً بالتمتع، فإذا وصل مكة طاف وسعى وقصر وتحلل لعمرته، إذا كان ما معه هدي يطوف ويسعى ويقصر ويحل وتمت عمرته، ثم إذا جاء اليوم الثامن من ذي الحجة يبدأ بالحج، ولكن الأفضل إذا كان الحج -يعني متأخر- يلبي بالعمرة فقط: اللهم لبيك عمرة بس ويكتفي، ولا يذكر الحج إلا في وقته، فيقول: اللهم لبيك عمرة فيطوف ويسعى ويقصر ويحل، وإذا جاء يوم الثامن من ذي الحجة عند صعوده إلى منى يلبي بالحج، هذا هو التمتع الأفضل، وإن كان متأخراً بأن جاء في يوم عرفة مثلاً، أو في يوم الثامن ...... بعد صعوده إلى منى ولبى بالحج والعمرة جميعاً فلا بأس، يسمى: قارناً ويسمى: متمتعاً، وإن دخل مكة وطاف وسعى وخرج على إحرامه ولم يقصر؛ لأنه قارن فلا بأس، وإن قصر في الحال وتمم عمرته ثم لبى بالحج يكون هذا، أفضل ولو كان في اليوم الثامن أو في التاسع. نعم.","link":"https://binbaz.org.sa/fatwas/5908/صفة-تلبية-المتمتع-وقت-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08704.mp3","categories":["الإحرام"]},{"id":8115,"question":"لأنه قال بعدها: ماذا معنى مفرد؟ وماذا معنى قران؟ وما تمتع؟","title":"معنى الإفراد والقران والتمتع","answer":"الجواب: هذا شيئاً آخر وإذا كان يسأل عن الإفراد: معناه: أنه يلبي بالحج مفرداً، هذا تسمى: مفرد.\nالمقدم: يعني ما معاه عمرة؟\nالشيخ: ما معاه عمرة يقول: اللهم لبيك حجاً، ويبقى على إحرامه، حتى ينتهي من الحج، هذا يسمى: مفرداً، وإن قال: لبيك عمرة، هذا يسمى: متمتعاً إذا كان في قبل الحج، ثم حج إذا كان بعد رمضان قال: لبيك عمرة ونيته البقاء حتى يحج، هذا يسمى: متمتعاً، أو قال: لبيك عمرة وحجاً يسمى: قارناً، والسنة له أنه لا يبقى على حاله، بل يطوف ويسعى ويحل ويكون متمتع، هذا هو الأفضل، هذا هو السنة له، لا يبقى على إحرامه، وهكذا الحاج إن لبى بالحج مفرداً، فالسنة له أنه يطوف ويسعى ويقصر ويحل، يكون متمتع يكون عمرة؛ لأن الرسول ﷺ أمر الصحابة الذين أحرموا بالحج مفرداً أو بالحج والعمرة جميعاً، لما دخلوا في ذي القعدة أمرهم أن يجعلوها عمرة، فيطوفوا ويسعوا ويقصروا ويجعلوها عمرة، هذا السنة، إلا إذا كان معه هدي إبل أو بقر أو غنم، ولو رأساً واحداً الذي معه شيء يبقى على إحرامه، سواءً كان مفرداً أو قارناً أو ملبياً بالعمرة، فإنه يبقى على إحرامه ويلبي بالحج مع العمرة، يبقى حتى يحل من حجه وعمرته جميعاً يوم النحر.\nالمقدم: أحسنتم، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5914/معنى-الافراد-والقران-والتمتع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08706.mp3","categories":["الإحرام"]},{"id":8733,"question":"أخونا السوداني الكسلاوي بابكر صالح الشريسابي يسأل ويقول: أعلم أن الحج ثلاثة أقسام: قران، وتمتع، وإفراد، وأريد منكم أن تحدثوني عن كل جزاكم الله خيرًا؟","title":"بيان أنساك الحج الثلاثة","answer":"الجواب: نعم، هو كما ذكرت، الأنساك ثلاثة: حج مفرد، وعمرة مفردة، وقران بينهما، وقد أجمع العلماء على جواز الأنساك الثلاثة والحمد لله، وإنما اختلفوا في الأفضل، وقد دلت الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام أن الأفضل هو التمتع بالعمرة، كون المتوجه من بلده إلى مكة يحرم بالعمرة أولًا، إذا كان في أشهر الحج يحرم بالعمرة متمتعًا بها إلى الحج فيلبي فيقول: اللهم لبيك عمرة، أو اللهم قد أوجبت عمرة ونحو هذه العبارة، بعدما يتأهب لذلك، بعدما يغتسل ويتطيب هذا هو الأفضل، يغتسل ويتطيب في بيته أو في المطار أو في بيت إن كان قريب من المطار أو في الطريق يغتسل ويتنظف ويأخذ ما يحتاج إلى أخذه من قص شارب أو قلم ظفر أو نتف إبط أو حلق عانة إذا دعت الحاجة إلى ذلك من باب النظافة، ويتطيب في بدنه في لحيته ورأسه وبدنه لا في الملابس بل في بدنه، ثم يلبس ملابس الإحرام إزارًا ورداء إن كان رجلًا، والمرأة تلبس ما شاءت من الملابس لكن تكون ملابس غير جميلة وغير لافتة للنظر حتى لا تفتن أحدًا بسبب الخلطة في المطاف بالطواف وغيره، ثم بعد هذا كله يركب المؤمن أو المؤمنة السيارة فيلبي وهو في السيارة راكبًا؛ لأن الرسول ﷺ كان يلبي إذا انبعثت به راحتله إذا قام به جمله لبى بعد ذلك وهو راكب عليه الصلاة والسلام هذا هو الأفضل، وإن أحرم وهو في الأرض قبل أن يركب فلا بأس، لكن الأفضل أنه يتأهب وهو في الأرض بما شرع الله من الغسل والطيب والتنظف ثم يلبس ملابس الإحرام ثم يركب، ثم يلبي بعد الركوب فيقول: اللهم لبيك عمرة؛ إذا كان متمتعًا بالعمرة إلى الحج، أو كان قصد العمرة في غير أوقات الحج كرمضان وغيره.\nفإذا وصل إلى مكة وهو متمتع بالعمرة إلى الحج بعد رمضان طاف وسعى وقصر وتحلل، فإذا طاف بالبيت سبعة أشواط، ثم سعى بين الصفا والمروة سبعة أشواط يبدأ بالصفا ويختم بالمروة، ... بدأها بالصفا وختم بالمروة.\nأما الطواف يبدأ بالحجر الأسود ويختم به، بالحجر الأسود يبدأ به ويختم به سبعة أشواط من وراء الحجر لا يدخل الحِجر، لا يدخل في الفرجة التي في الحِجر لا، بل يطوف من وراء الحِجر وقد يغلط بعض الحجاج في ذلك، فالواجب أن يطوف من وراء الحِجر سبعة أشواط من الحَجر إلى الحَجر، ثم يصلي ركعتين، ركعتي الطواف خلف مقام إبراهيم أو في أي مكان من الحرم، ثم بعد ذلك يذهب إلى السعي فيسعى سبعة أشواط يبدأ بالصفا ويختم بالمروة، ويمشي مشي العادة إلا في بطن الوادي فإنه يهرول بين العلمين الموضوعين هناك، ويكبر على الصفا والمروة، يكبر الله، ويذكره، ويدعوه ثلاث مرات، كما أنه يذكر الله ويدعوه في الطواف بما يسر الله له، وإن قرأ القرآن فلا بأس، ليس فيه شيء محتم ما تيسر ، يذكر الله في طوافه ويدعو في طوافه ويقرأ القرآن كله طيب والحمد لله.\nوهكذا في السعي يدعو الله بما تيسر ويذكر الله بما تيسر ويقرأ القرآن إذا أحب، وعلى الصفا يكرر الذكر والدعاء ثلاث مرات كما فعله النبي ﷺ، وهكذا على المروة، فالبدء يكون بالصفا والختام يكون بالمروة، ثم يحلق إن كان رجلًا أو يقصر وتمت العمرة، والمرأة تقصر فقط ليس لها حلق لا تحلق رأسها، ولكن تقصر من كل أطراف الشعر قليلًا، إن كان الشعر مفتول من كل عميلة قليل، وإن كان غير مفتول بل منقوض جمعت شعرها وقصت من أطرافه قليلًا والرجل كذلك، وبهذا تمت العمرة، وحل للرجل والمرأة كل شيء حرم عليهم بالإحرام، حل له جماع زوجته، حل له لبس المخيط، حل له الطيب كسائر الحلال كسائر المحلين.\nفإذا جاء يوم الثامن من ذي الحجة لبى بالحج الرجل والمرأة، هذا هو الأفضل وهذا هو الذي أمر به النبي ﷺ أصحابه في حجة الوداع لما قدموا وبعضهم قد أحرم بالحج مفردا، وبعضهم قد أحرم بالحج والعمرة جميعًا قارنًا، قال لهم: اجعلوها عمرة فطافوا وسعوا وقصروا وحلوا، فلما كان يوم الثامن أمرهم أن يلبوا بالحج عند توجههم إلى منى، أما هو ﷺ فكان قد أحرم بالحج والعمرة جميعًا قارنًا لأن معه الهدي، لأنه قد ساق معه إبلًا من المدينة هديًا تذبح في مكة، والمهدي لا يحل؛ فلهذا أحرم بالحج والعمرة جميعًا فمن كان مثل النبي ﷺ أحرم بالحج والعمرة جميعًا، إذا كان مهديًا إبلًا أو بقرًا أو غنمًا يلبي بالحج والعمرة جميعًا هذا هو الأفضل، ولا يحل حتى يحل يوم النحر.\nالنسك الثاني: الإحرام بالحج والعمرة جميعًا، يقول: اللهم لبيك عمرة وحجًا. في الميقات ميقات بلده، هذا هو النسك الثاني، والأفضل تركه، وهو أن يقول: اللهم لبيك عمرة وحجًا، أو يقول: اللهم لبيك عمرة، ثم في أثناء الطريق يلبي الحج ويدخله على العمرة فيكون قارنًا بين الحج والعمرة، فإن كان معه هدي فهذا هو الأفضل له، ويبقى على إحرامه حتى يوم العيد مثلما فعل النبي ﷺ، وإن كان ما معه هدي شرع له أن يحل كما حل الصحابة بأمر النبي ﷺ فيطوف ويسعى ويقصر ويجعلها عمرة، وإن كان قد لبى بالحج والعمرة جميعًا عند الميقات، فالسنة له أن يطوف ويسعى ويقصر ويتحلل ويجعل إحرامه عمرة ويسمى فسخًا يقال: فسخ إحرامه من القران إلى العمرة كما أمر النبي أصحابه بذلك عليه الصلاة والسلام.\nوهكذا يفعل من أحرم بالحج من الميقات مفردًا وهو النسك الثالث قال: اللهم لبيك حجا، أو اللهم قد أوجبت حجا، يعني: في الميقات، فإن كان معه هدي يبقى على إحرامه ولا يحل حتى يحل يوم العيد، وإن كان ما معه هدي ليس معه إبل ولا بقر ولا غنم؛ فإنه يفسخ حجه بالعمرة مثلما فعل القارن سابقًا، فيطوف ويسعى ويقصر ويتحلل، تكون عمرة، كما أمر النبي ﷺ أصحابه المفردين بذلك، فإذا كان اليوم الثامن لبى بالحج قال: اللهم لبيك حجا، يعني: يغتسل ويتطيب مثلما فعل في الميقات، إذا تيسر يغتسل ويتطيب ويتنظف إن احتاج إلى ذلك من قص الشارب ونحوه ثم يلبي بالحج وهو في منزله في خيمته .. في الأبطح .. في داخل مكة، في أي مكان، يفعل ما يشرع من الآداب الشرعية عند إحرامه .. الغسل والطيب ونحو ذلك، ثم يلبي في مكانه ما في حاجة يدخل إلى مكة حتى يطوف، ما في وداع عند الخروج إلى منى ما في وداع، يحرم من منزله سواء كان في الأبطح أو كان في ...، أو كان في أي مكان من مكة أو في ضواحيها يحرم من مكانه في الخيام أو في المنازل هذه السنة، وإن دخل مكة وطاف فلا حرج، لكن خلاف السنة، السنة أنه يحرم من مكانه ويتوجه إلى منى ملبيًا، والأفضل إذا كان عنده مركوب؛ ألا يلبي حتى يركب كما تقدم في الميقات هذا هو الأفضل، فإن كان ماشيًا على قدميه إلى منى فعند توجهه ماشيًا يلبي، يقول: اللهم لبيك حجًا، ثم يكثر من التلبية في الطريق من الميقات، الذي أحرم من الميقات يلبي، والذي أحرم من منزله بالحج يلبي كلهم يلبون، من الميقات إلى مكة، ومن منزله حين خروجه إلى منى كذلك يلبي: (لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك)، النبي كان يلبي بهذه التلبية عليه الصلاة والسلام في طريقه من المدينة إلى أن وصل مكة يكثر منها ويرفع صوته عليه الصلاة والسلام، يقول: «إن جبرائيل أمرني أن آمر أصحابي أن يرفعوا أصواتهم بالإهلال» يعني: بالتلبية، فكان يلبي ويجهر ويأمر أصحابه بذلك عليه الصلاة والسلام؛ لأن هذا شعار الحج شعار عظيم، فالسنة رفع الأصوات بذلك ... رفعًا لا يضر أحدًا، هذا هو السنة، وهذه هي الأنساك الثلاثة وهذه أعمالها. نعم..\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6887/بيان-انساك-الحج-الثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16105.mp3","categories":["الإحرام"]},{"id":8826,"question":"سماحة الشيخ! الذي ما يتابع ما تفضلتم به يلحظ أن حجة النبي ﷺ كانت قران، ونسمع كثيرًا من المفتين يفتون بأن التمتع أفضل، كيف تناقشون هذا لو سمحتم؟","title":"التمتع أفضل أنواع الحج","answer":"الجواب: نعم، النبي ﷺ لما قدم مكة أمر الصحابة أن يجعلوا إحرامهم عمرة للذين ليس معهم هدي، وقد أفردوا الحج أو قرنوا فقال: اجعلوها عمرة، ولولا أن معي الهدي لأحللت وقال أيضًا عليه الصلاة والسلام: لو استقبلت من أمري ما استدبرت ما أهديت ولا جعلتها عمرة.\nفهذا هو وجه قول العلماء أنه يستحب التمتع؛ لأن الرسول رجع إليه عليه الصلاة والسلام، وأمر به الصحابة، وأحب أن يكون فعل ذلك، لكن من أحب أن يحرم بإحرامه قارنًا وهو مهدي فلا بأس؛ لأنه ﷺ لم يمنع من هذا النسك، وإنما أمر أصحابه أن يحلوا إلا من كان معه الهدي وبقي على حاله، فدل ذلك على أن القران باقي لمن معه الهدي؛ لأن الرسول لم يبطله عليه الصلاة والسلام بل استمر عليه.\nلكن كونه يحرم بالتمتع ولا يهدي أفضل، يشتري من مكة أو من منى بعد ذلك عند الحاجة، ولا يهدي؛ لأن في الهدي والبقاء على الإحرام مشقة كبيرة؛ قد يندم عليها الإنسان، ولا سيما إذا طال الأمر، فقد يقدم في آخر ذي القعدة أو في أول ذي الحجة، فكونه يبقى محرمًا لا يتطيب ولا يقص ظفرًا ولا شاربًا ولا يأتي أهله قد يشق عليه ذلك، فمن رحمة الله أن شرع لنا التمتع، وألا نكلف أنفسنا هذه الكلفة.\nفلنشتري هدينا من داخل ولا حاجة إلى أن نهدي من خارج، إذا جاء يوم العيد أو أيام التشريق اشترى الإنسان هديه من منى أو من مكة وذبحه والحمد لله، ولا يشق على نفسه بالبقاء محرمًا من أول ذي الحجة أو من آخر ذي القعدة إلى يوم العيد لا يتطيب ولا يقص شعرًا ولا ظفرًا ولا يأتي أهله، كل هذا فيه صعوبة على الرجال والنساء جميعًا، نعم، ومن رحمة الله أن شرع التمتع لما فيه من الراحة والتيسير وعدم التكلف. نعم.","link":"https://binbaz.org.sa/fatwas/6980/التمتع-افضل-انواع-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_164/16402.mp3","categories":["الإحرام"]},{"id":9041,"question":"السؤال الثاني -في رسالة الأخ المواطن: عادل عبدالحميد حسن من جمهورية مصر العربية ومقيم في الأردن- يقول فيها: دائماً ما أسمع في أشهر الحج عن الأنساك، ما هي هذه الأنساك وكم عددها؟ أفيدوني أفادكم الله.","title":"ما هي أنساك الحج؟","answer":"الجواب: الأنساك ثلاثة: أحدها: إفراد الحج بأن يقول: اللهم لبيك حجاً، أو لبيك حجة، هذا يقال له: إفراد الحج، والأفضل أن يكون ذلك في أشهر الحج، وهي شوال وذو القعدة وذو الحجة، يعني: العشر الأولى منها، فإذا قال: اللهم لبيك حجاً صار مفرداً بالحج، فيبقى على إحرامه حتى يقف بعرفة يوم التاسع، وحتى يبيت في مزدلفة ليلة العاشرة من ذي الحجة، وحتى يطوف بالبيت العتيق سبعة أشواط ويصلي ركعتين خلف المقام -مقام إبراهيم - ويسعى بين الصفا والمروة سبع مرات، هذا هو أعمال الحج، وعليه مع ذلك أن يكمل أعمال الحج برمي الجمار يوم العيد وأيام التشريق، والمبيت في ليالي منى، كل هذا من أعمال الحج، وليس عليه هدي لأنه مفرد بالحج.\nالنسك الثاني: العمرة وحدها، وهي تفعل في جميع السنة، في رمضان وفي شوال وفي غيرهما، وهي أن يحرم بعمرة، فيقول: لبيك عمرة، من الميقات الذي يرد منه، فإن كان ورد من المدينة فميقات المدينة، وإن قدم من اليمن فميقات اليمن، وإن كان قدم من مصر أو الشام أو الغرب فمن ميقات الشام ومصر والمغرب وهو الجحفة وهو المعروف الآن برابغ، وإن كان قدم من جهة الشرق أو من جهة الطائف فمن قرن -وادي قرن-، ومن جهة العراق من ذات عرق، فيلبي بالعمرة من هذه المواقيت التي يمر بها، إذا مر على واحد من هذه المواقيت يلبي بالعمرة من ذلك الميقات، يقول: اللهم لبيك عمرة أو لبيك عمرة، أو قد أوجبت عمرة وهي الزيارة، العمرة هي الزيارة للبيت -البيت العتيق- فيلبي بالتلبية الشرعية كالحج سواء لبيك اللهم لبيك، لبيك لا شريك لك لبيك إن الحمد والنعمة لك والملك لا شريك لك، فإذا وصل إلى البيت العتيق طاف به سبعة أشواط وصلى ركعتين خلف المقام، ثم سعى بين الصفا والمروة سبعة أشواط، ثم قص من شعره أو حلقه، قصه أن يقطع أطراف الشعر بالمقراض يعمه بالمقراض، والحلق أن يأخذه بالموسى، أو بالمكينة التي تأخذه كله هذه هي العمرة، وهي زيارة البيت العتيق في جميع السنة.\nالنسك الثالث: أن يجمع بينهما، بين الحج والعمرة جميعاً، فيقول: اللهم لبيك عمرة وحجة، أو لبيك عمرة وحجة، أو اللهم قد أوجبت عمرة وحجة، فهذا يقال له: القران، وهو الجمع بين العمرة والحج جميعاً.\nوهناك صفة أخرى في الجمع بينهما، وهي أن يلبي بالعمرة في أشهر الحج شوال أو ذي القعدة أو ذي الحجة، ويفرغ منها.. بالطواف والسعي والتقصير، ثم يلبي بالحج في وقته، في اليوم الثامن من ذي الحجة أو قبله أو بعده، فهذا يسمى تمتع لأنه تمتع بالعمرة إلى الحج، أدى مناسكها وتمتع بعد ذلك بما أباح الله له من الطيب والنساء وغير ذلك، ثم لبى بالحج بعد ذلك، فهذا يقال له: متمتع، ويسمى القارن: متمتع أيضاً؛ لأنه جمع بين الحج والعمرة، هذه هي الأنساك الثلاثة التي بينها الرسول صلى الله عليه وسلم وبينها أهل العلم، وكلها جائزة وكلها مشروعة، لكن الأفضل لمن جاء إلى مكة في أشهر الحج أن يتمتع، هذا هو الأفضل إذا جاء في شوال أو في ذي القعدة أو في العشر الأولى من ذي الحجة فالأفضل له أن يلبي بالعمرة ثم يطوف ويسعى ويقصر ويحل ثم يلبي بالحج، هذا هو الأفضل، والله ولي التوفيق. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7201/ما-هي-انساك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22402.mp3","categories":["الإحرام"]},{"id":9042,"question":"هذه رسالة وصلت إلى البرنامج من المستمع: هشام محمد يوسف المصري من المدينة المنورة، يقول في رسالته وفي سؤاله الأول: إذا اعتمر الإنسان في أشهر الحج، ثم حج من عامه، فهل يعتبر متمتعاً ويلزمه دم، حتى لو سافر بينهما، أفيدونا أفادكم الله؟","title":"حكم من اعتمر في أشهر الحج ثم أراد أن يحج","answer":"الجواب: نعم، إذا اعتمر المسلم في أشهر الحج شوال أو في ذي القعدة أو في العشر الأول من ذي الحجة ثم حج من عامه، فإنه يسمى متمتعاً ويعتبر متمتعاً وعليه دم التمتع، وهو سبع بدنة، أو سبع بقرة، أو ثني من المعز أو جذع من الضأن يذبح في مكة للفقراء، ويأكل منه ويهدي منه، هذا هو الواجب عليه، لكن إن سافر بينهما سفراً قصيراً فإنه لا يضر، هو السفر الذي لا تقصر فيه الصلاة كضواحي مكة ونحوها لا يضر ولا يمنع من الدم.\nأما إن سافر سفراً تقصر فيه الصلاة كأن سافر إلى المدينة أو إلى الطائف ونحو ذلك، فهذا فيه خلاف بين أهل العلم، بعض أهل العلم قال: إنه يكون مفرداً بالحج فيسقط عنه الدم؛ لأنه سافر بينهما وأتى بحج مفرد، وذهب آخرون من أهل العلم: إلى أنه لا يكون مفرداً بكل يكون متمتعاً ولو سافر إلى المدينة أو إلى الطائف أو إلى غيرهما أو إلى جدة ونحو ذلك، بل يكون باقياً على تمتعه وعليه الدم، وهذا هو الأرجح وهذا هو الأقرب لعموم الأدلة؛ لأن الله قال جل وعلا: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196]، فهذا العموم يدل على أنه ولو سافر بينهما عليه دم التمتع.\nوذهب جمع من أهل العلم -أيضاً-: إلى أنه إذا سافر إلى أهله، ثم رجع بحج مفرد، فإنه يسقط عنه الدم، وهذا ثابت عن عمر  وأرضاه وابنه عبد الله، هذا يستثنى من العموم إذا سافر إلى أهله خاصة، ثم رجع بحج مفرد، فإنه يسقط عنه الدم عند الأكثر من أهل العلم.\nمذهب ابن عباس رضي الله عنهما إلى أن الدم على جميع من تمتع بالعمرة إلى الحج ولو سافر إلى أهله أو إلى غير أهله مطلقاً، ما دام أدى العمرة في أشهر الحج، ثم حج من عامه فإن عليه الفدية، والذي عليه جمهور أهل العلم: أنه إذا سافر إلى أهله ثم أتى بحج مفرد، فإنه لا دم عليه، وهذا هو الأقرب إن شاء الله، وإن فدى احتياطاً كما قال ابن عباس رضي الله عنهما فهذا حسن من باب: دع ما يريبك إلى ما لا يريبك.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7207/حكم-من-اعتمر-في-اشهر-الحج-ثم-اراد-ان-يحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22406.mp3","categories":["الإحرام"]},{"id":9049,"question":"هذه رسالة وصلت إلى البرنامج من المستمع: هشام محمد يوسف المصري من المدينة المنورة، يقول في رسالته وفي سؤاله الأول: إذا اعتمر الإنسان في أشهر الحج، ثم حج من عامه، فهل يعتبر متمتعاً ويلزمه دم، حتى لو سافر بينهما، أفيدونا أفادكم الله؟","title":"حكم من اعتمر في أشهر الحج ثم أراد أن يحج","answer":"الجواب: نعم، إذا اعتمر المسلم في أشهر الحج شوال أو في ذي القعدة أو في العشر الأول من ذي الحجة ثم حج من عامه، فإنه يسمى متمتعاً ويعتبر متمتعاً وعليه دم التمتع، وهو سبع بدنة، أو سبع بقرة، أو ثني من المعز أو جذع من الضأن يذبح في مكة للفقراء، ويأكل منه ويهدي منه، هذا هو الواجب عليه، لكن إن سافر بينهما سفراً قصيراً فإنه لا يضر، هو السفر الذي لا تقصر فيه الصلاة كضواحي مكة ونحوها لا يضر ولا يمنع من الدم.\nأما إن سافر سفراً تقصر فيه الصلاة كأن سافر إلى المدينة أو إلى الطائف ونحو ذلك، فهذا فيه خلاف بين أهل العلم، بعض أهل العلم قال: إنه يكون مفرداً بالحج فيسقط عنه الدم؛ لأنه سافر بينهما وأتى بحج مفرد، وذهب آخرون من أهل العلم: إلى أنه لا يكون مفرداً بكل يكون متمتعاً ولو سافر إلى المدينة أو إلى الطائف أو إلى غيرهما أو إلى جدة ونحو ذلك، بل يكون باقياً على تمتعه وعليه الدم، وهذا هو الأرجح وهذا هو الأقرب لعموم الأدلة؛ لأن الله قال جل وعلا: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196]، فهذا العموم يدل على أنه ولو سافر بينهما عليه دم التمتع.\nوذهب جمع من أهل العلم -أيضاً-: إلى أنه إذا سافر إلى أهله، ثم رجع بحج مفرد، فإنه يسقط عنه الدم، وهذا ثابت عن عمر  وأرضاه وابنه عبد الله، هذا يستثنى من العموم إذا سافر إلى أهله خاصة، ثم رجع بحج مفرد، فإنه يسقط عنه الدم عند الأكثر من أهل العلم.\nمذهب ابن عباس رضي الله عنهما إلى أن الدم على جميع من تمتع بالعمرة إلى الحج ولو سافر إلى أهله أو إلى غير أهله مطلقاً، ما دام أدى العمرة في أشهر الحج، ثم حج من عامه فإن عليه الفدية، والذي عليه جمهور أهل العلم: أنه إذا سافر إلى أهله ثم أتى بحج مفرد، فإنه لا دم عليه، وهذا هو الأقرب إن شاء الله، وإن فدى احتياطاً كما قال ابن عباس رضي الله عنهما فهذا حسن من باب: دع ما يريبك إلى ما لا يريبك.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7207/حكم-من-اعتمر-في-اشهر-الحج-ثم-اراد-ان-يحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22406.mp3","categories":["الإحرام"]},{"id":9072,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع سلمان محمد بن مسعود من دولة قطر الشقيقة، يقول فيها: من المتعارف عليه أن طريقة لباس الإحرام هي أن يكشف الحاج عن منكبه الأيمن ويغطي منكبه الأيسر، بحيث تظهر يده اليمنى إلى الكتف، ويغطي الكتف اليسرى من جهة الصدر والظهر، ولكنني رأيت بعض الحجاج يغطون الكتفين معاً، وهناك من يكشف عن الكتفين، فأرجو التكرم بإيضاح هذه المسألة لتعم الفائدة، جزاكم الله خيراً؟","title":"بيان السنة في كيفية لبس المحرم للإحرام","answer":"الجواب: السنة للمحرم أن يجعل الرداء على كتفيه جميعاً، السنة أن يجعل الرداء على كتفيه جميعاً، وأن يجعل طرفيه على صدره، هذا هو السنة، وهذا هو الذي فعله النبي عليه الصلاة والسلام، فإذا أراد أن يطوف طواف القدوم، اضطبع، فجعل وسط ردائه تحت إبطه الأيمن وأطرافه على عاتقه الأيسر، وكشف منكبه الأيمن في حالة الطواف ... فقط، طواف القدوم خاصة، يجعل وسط الرداء تحت إبطه الأيمن وأطراف الرداء على عاتقه الأيسر، ويكشف منكبه الأيمن في حال طواف القدوم، أول ما يقدم مكة في الحج أو في العمرة، هذا هو السنة التي فعلها النبي ﷺ، ومن فعل خلاف ذلك فقد خالف السنة، الذي يكشف منكبه دائماً هذا خلاف السنة، والذي يكشف المنكبين دائماً خلاف السنة، وإنما السنة أن يسترهما بالرداء، هذا هو السنة حال كونه محرماً، ولو وضع الرداء ولم يسترهما في وقت جلوسه أو وقت أكله أو تحدثه مع إخوانه لا بأس، لكن السنة إذا لبس الرداء أن يكون على كتفيه وأطرافه على صدره، هذا هو السنة، إلا في حال طواف القدوم أول ما يقدم مكة، فإنه يضطبع كما فعل النبي ﷺ والاضطباع هو أن يجعل وسط الرداء تحت إبطه الأيمن وطرفيه على عاتقه الأيسر، ويكون المنكب الأيمن مكشوفاً، فإذا انتهى من الطواف عدل الرداء جعله على منكبيه وصلى ركعتي الطواف وهو قد عدل الرداء وجعله على منكبيه كما كان قبل أن يطوف هذا هو السنة. نعم.","link":"https://binbaz.org.sa/fatwas/7233/بيان-السنة-في-كيفية-لبس-المحرم-للاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_225/22505.mp3","categories":["الإحرام"]},{"id":9074,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع الحاج: رفعت كمال الدين من جمهورية مصر العربية يقول فيها: نحن مجموعة من الحجاج نود أن توضحوا لنا لماذا جعل الإحرام على ثلاثة أنواع هي: القران، التمتع، والإفراد؟ وأي الأنواع الثلاثة أسهل للحاج؟ وكيف كان إحرام رسول الله ﷺ؟","title":"الحكمة من أنساك الحج الثلاثة","answer":"الجواب: الله سبحانه شرع الأنساك الثلاثة لحكمة بالغة ومنها: التيسير على الأمة والتوسعة لهم، فإن بعض الناس قد يريد العمرة فقط ولا يريد الحج؛ لأنه قد حج سابقاً فيأتي بعمرة وحدها، وينتفع بهذا النسك العظيم، والعمرة كفارة لما بينها وبين العمرة الأخرى، فيها خير عظيم، والحج مفرداً فيه أيضاً تيسير على الحاج؛ لأنه يؤدي الحج من دون عمرة ، فلا يتكلف العمرة ولا يتكلف بالدم؛ لأن المتمتع عليه دم، فيأتي بالحج مفرداً، فيلبي بالحج مفرداً ويفعل أفعال الحج إذا وصل إلى مكة، يطوف طواف القدوم ويسعى مع ذلك ويبقى على إحرامه حتى يقف بعرفات وحتى يكمل الحج، وليس عليه دم يسمى: مفرداً.\nوالنوع الثالث: يسمى: قارناً ويسمى: متمتعاً، وهو الذي يأتي بالعمرة والحج جميعاً، فإن جمع بينهما في التلبية قال: لبيك عمرة وحجاً، أو: اللهم لبيك عمرة وحجاً، أو: اللهم قد أوجبت عمرة وحجا، فهذا حكمه حكم المفرد في العمل، يطوف ويسعى إذا قدم مكة ، ويبقى على إحرامه، فإذا جاء يوم عرفة وقف مع الناس، وبات في المزدلفة ثم رمى الجمرة يوم العيد ثم كمل حجه وعليه دم؛ لأنه جمع بين الحج والعمرة ذبيحة، أو سبع بدنة أو سبع بقرة تذبح في مكة أو في منى للفقراء والمساكين، ويأكل منها ويطعم منها.\nوالنوع الثاني من التمتع: أن يحرم بالعمرة ثم يحل منها، يطوف ويسعى ويقصر ويحل في أشهر الحج: شوال أو ذي القعدة أو ذي الحجة، ثم يلبي بالحج مع الناس في اليوم الثامن من ذي الحجة أو قبله، فيقف مع الناس في عرفات وفي مزدلفة وفي المشعر الحرام. إلى غير ذلك ويكمل الحج على هذا، فهذا يسمى: متمتعاً، وعليه كالذي قبله دم كالقارن، عليه دم، وهو دم التمتع يذبح في مكة، أو في منى، ويأكل منه ويطعم كما فعل القارن.\nهذا هو الفرق بين هذه الأنساك الثلاثة، والحكمة في ذلك -والله أعلم- والفائدة التوسعة والتيسير على الحجاج، من أراد الحج وحده أحرم بالحج وحده، ومن أراد العمرة وحدها أحرم بالعمرة وحدها في أي وقت، ومن أراد الحج والعمرة جميعاً جمع بينهما بنسك واحد، أو أحرم بالعمرة وفرغ منها ثم أحرم بالحج، فإذا قدم قارناً أو مفرداً بالحج قبل وقت الحج، فالسنة له أن يحل، السنة له والمشروع له أنه يحل ما يبقى محرماً؛ لأن هذا يشق عليه ويتعبه، وهو خلاف السنة، فالنبي ﷺ أمر الحجاج.. أمر الصحابة لما قدموا في رابع ذي الحجة، وقد أحرم بعضهم بالقران وبعضهم بالعمرة وتحلل منها أمرهم أن يتحللوا كان بعضهم قد أحرم بالقران وبعضهم أحرم بالحج مفرداً، فأمرهم ﷺ أن يتحللوا، بأن: يجعلوها عمرة فيطوفوا ويسعوا ويقصروا ويحلوا، فطافوا وسعوا وقصروا وحلوا، وأمرهم بالهدي هدي التمتع، ومن لم يجد صام عشرة أيام ثلاثة أيام في الحج وسبعة إذا رجع إلى أهله، هذا هو الأفضل، وهو أنه يحرم بالعمرة فإذا فرغ منها، ثم يحرم بالحج ويهدي هذا هو الأفضل، وهذا هو الذي أمر به النبي ﷺ أصحابه، وقال: لو استقبلت من أمري ما استدبرت ما أهديت ولجعلتها عمرة تمنى أنه فعل مثلهم، فالأفضل للقادم إلى مكة في أشهر الحج أنه يلبي بالعمرة ثم إذا فرغ منها وجاء وقت الحج أحرم بالحج ويسمى: متمتعاً وهذا هو الأفضل، وهو الذي أمر به النبي ﷺ الصحابة  وأرضاهم، وأرشدهم إلى ذلك، وتمنى أنه يتمكن من ذلك لولا أن معه الهدي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/7234/الحكمة-من-انساك-الحج-الثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_225/22506.mp3","categories":["الإحرام"]},{"id":9402,"question":"السؤال الثاني لأخينا من السودان والمقيم في قطر عن الأطفال هل يلزمون بلبس الإحرام عند العمرة أو الحج؟","title":"حكم إلزام الأطفال بلبس الإحرام أثناء الحج أو العمرة","answer":"الجواب: نعم، الأطفال مثل الكبار، إذا نوى عنهم وليهم المسئول عنه في السفر كأبيهم أو أمهم أو أخيهم المسئول عنهم في هذا السفر الذي حج بهم، إذا تولى عنهم الإحرام بأن كانوا دون السبع فنوى عنهم الإحرام أو فوق السبع وأمروا بالإحرام يعلمون، فالذي فوق السبع يعلم يقال له إن كان ذكر: اخلع الملابس المخيطة والبس إزارًا ورداء واكشف رأسك، وإن كان صغيرًا دون السبع كشف رأسه وألبس قطعة من ... وجرد من القميص والفنيلة مثلًا والسراويل ولف في اللفافة وضبطت عليه حتى يكمل عمرته أو حجه.\nوهكذا الكبير الذي فوق السبع يعلمه وليه يقال له: سو كذا وسو كذا وسو كذا، أما الأنثى فلا فإحرامها في وجهها ما عليها تلبس ما شاءت من الملابس، تحرم في ملابسها العادية وإذا أحرمت بملابس غير لافتة للنظر -يعني: غير جميلة- يكون ذلك أولى وأفضل حتى لا تلفت النظر، وحتى لا تفتن أحدًا؛ لأنها تخالط الناس فقد يبين منها شيء من هذه الملابس التي قد تفتن الناس.\nوهكذا الصغيرة تلبس ملابس مناسبة للمقام ليس فيها زينة كثيرة، بل ملابس عادية، وتكشف وجهها؛ لأنها صغيرة، فإذا كانت ممن يغطى وجهه كالمراهقة والكبيرة يغطى وجهها بما معهم من الخمار من دون نقاب، النقاب تمنع من النقاب وما يصنع للوجه من الملابس التي تصنع للوجه ويكون فيها نقب للعين أو للعينين، وبعضهم يلفه على الوجه، يجعل غطاءً للوجه على قدره يغطي الأنف والفم والجبهة وتبقى العينان، هذا كله تمنع منه، وتغطي وجهها بالخمار ونحوه، كما قالت عائشة رضي الله عنها: كنا مع النبي ﷺ في الحج وكنا إذا دنا منا الرجال سدلت إحدانا خمارها على وجهها، فإذا بعدوا عنا كشفنا نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7567/حكم-الزام-الاطفال-بلبس-الاحرام-اثناء-الحج-او-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18808.mp3","categories":["الإحرام"]},{"id":9685,"question":"الأخ أحمد حسن عبدالرحيم من مصر أيضاً يقول: هناك كثير من الناس يقول: بأن الحاج إذا نوى الحج لا بد أن يقوم له من بلده، فلا يصلح أن يكون مثلاً في مكة فيحج منها إذا كان قادماً للعمل؟","title":"حكم من دخل مكة ثم نوى الحج وهو فيها","answer":"الجواب: لا حرج عليه ولو من مكة، لو كان ما حج حج الفريضة وجاء في غير وقت الحج إلى مكة للعمل ولم يقصد عمرة ولا حجا، ثم عزم على الحج فإنه يحج من مكة ويكفي والحمد لله، يحرم من مكانه ويجزئه، وهكذا العمرة، إذا جاء ما قصد عمرة قصد العمل ثم بدا له أن يعتمر يحرم من الحل خارج مكة خارج الحرم يعني، من التنعيم أو الجعرانة، يخرج إلى الحل ثم يحرم بالعمرة، أما الحج فيجزئه أن يحرم من نفس مكة، لقول النبي ﷺ لما وقت المواقيت قال ﷺ: هن لهن، ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة، ومن كان دون ذلك فمهله من حيث أنشأ، حتى أهل مكة يهلون من مكة قال العلماء: معنى هذا أن أهل مكة يهلون من مكة يعني بالحج، أما العمرة فيخرج إلى الحل؛ لأن النبي ﷺ أمر عائشة لما أرادت العمرة وهي بمكة أن تخرج إلى الحل فتحرم من خارج مكة، يعني من خارج الحرم، فذهب بها عبد الرحمن أخوها وأعمرها من التنعيم، يعني: خارج حدود الحرم. نعم.\nالمقدم: بارك الله فيكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/7903/حكم-من-دخل-مكة-ثم-نوى-الحج-وهو-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25412.mp3","categories":["الإحرام"]},{"id":9849,"question":"يسأل أخيراً ويقول: أنا مقيم في جنوب المملكة، وقد توجهت إلى مكة المكرمة لأداء العمرة فتجاوزت الميقات دون إحرام، وأحرمت من جدة، فما الحكم في ذلك؟ بارك الله فيكم.","title":"حكم من تجاوز الميقات دون إحرام","answer":"الجواب: إذا كنت حين جاوزت الميقات ناوياً العمرة، فإن عليك دماً، عن ترك بعض الميقات؛ لأن جدة ليست ميقاتاً لك، وإنما هي ميقات لأهلها والمقيمين فيها.\nأما إذا كنت ما نويت العمرة إلا في جدة، وحين جاوزت الميقات لم تنو العمرة فلا شيء عليك، والواجب على كل مسلم إذا أراد العمرة أو الحج يحرم من الميقات الذي يمر عليه، فمن طريق المدينة يحرم من المدينة من ميقات المدينة، إن كان من طريق الساحل جاء من الشام أو مصر أحرم من رابغ، إن كان من اليمن أحرم من ميقات اليمن كيلملم، وإن كان من طريق نجد أو الطائف أحرم من ميقات الطائف، وادي قرن، هذا هو الواجب على المؤمن، ولا يتجاوز المواقيت بغير إحرام، أما إذا كان ما أراد حجاً ولا عمرة، وإنما جاء إلى جدة أو إلى مكة لحاجة لعمل لزيارة قريب أو صديق، ما قصد حجاً ولا عمرة، فهذا لا يلزمه الإحرام، ومتى أراد العمرة وأحرم من جدة أو من التنعيم خارج الحرم فلا بأس، في العمرة يعني، أما الحج فيحرم من حيث شاء، متى عزم على الحج يحرم ولو من مكة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8025/حكم-من-تجاوز-الميقات-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26213.mp3","categories":["الإحرام","المواقيت"]},{"id":10050,"question":"أحد الإخوة المستمعين يسأل ويقول: إذا وصلت إلى أحد المواقيت فهل أصلي ركعتين، أو أحرم ثم أصلي بعد الإحرام؟","title":"حكم الإحرام بعد الصلاة","answer":"الجواب: ليس هناك دليل واضح على صلاة ركعتين عند الإحرام، إلا أن النبي ﷺ أحرم بعد الصلاة، صلى الظهر في الحجة والوداع ثم أحرم، فأخذ بعض العلماء من ذلك أنه يستحب أن يكون الإحرام بعد الصلاة، وقد جاء في حديث آخر أنه ﷺ أتاه جبرائيل ، أتاه آتٍ من ربه فقال: صل في هذا الوادي المبارك، -يعني: وادي ذو الحليفة- وقل: عمرة في حجة.\nقالوا: فهذا يدل على شرعية الصلاة قبل الإحرام، قد ذهب أكثر أهل العلم إلى ذلك، ذهب الجمهور من أهل العلم إلى شرعية صلاة ركعتين قبل الإحرام، فإذا توضأ الإنسان وصلى ركعتين للوضوء وأحرم بعدها جمع بين القولين، جمع بين قول الجمهور وبين سنة الوضوء أو أحرم بعد الفريضة فريضة الظهر أو العصر أو غيرهما وافق السنة سواء للعمرة أو للحج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8226/حكم-الاحرام-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30310.mp3","categories":["الإحرام"]},{"id":10057,"question":"أحد الإخوة المستمعين يسأل ويقول: إذا وصلت إلى أحد المواقيت فهل أصلي ركعتين، أو أحرم ثم أصلي بعد الإحرام؟","title":"حكم الإحرام بعد الصلاة","answer":"الجواب: ليس هناك دليل واضح على صلاة ركعتين عند الإحرام، إلا أن النبي ﷺ أحرم بعد الصلاة، صلى الظهر في الحجة والوداع ثم أحرم، فأخذ بعض العلماء من ذلك أنه يستحب أن يكون الإحرام بعد الصلاة، وقد جاء في حديث آخر أنه ﷺ أتاه جبرائيل ، أتاه آتٍ من ربه فقال: صل في هذا الوادي المبارك، -يعني: وادي ذو الحليفة- وقل: عمرة في حجة.\nقالوا: فهذا يدل على شرعية الصلاة قبل الإحرام، قد ذهب أكثر أهل العلم إلى ذلك، ذهب الجمهور من أهل العلم إلى شرعية صلاة ركعتين قبل الإحرام، فإذا توضأ الإنسان وصلى ركعتين للوضوء وأحرم بعدها جمع بين القولين، جمع بين قول الجمهور وبين سنة الوضوء أو أحرم بعد الفريضة فريضة الظهر أو العصر أو غيرهما وافق السنة سواء للعمرة أو للحج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8226/حكم-الاحرام-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30310.mp3","categories":["الإحرام"]},{"id":10151,"question":"أحد الإخوة المستمعين بعث يقول: أنا مصري ومقيم في المملكة لي جمع من الأسئلة، أسأل أولاً هذا  لقد حضرت والدتي لأداء العمرة في شهر رمضان دون أن تحرم من الميقات، ثم أقامت ثلاثة أيام في جدة قبل أن تذهب إلى مكة لأداء العمرة، فهل عليها دم، أم لا؟","title":"حكم من قدم للعمرة وتجاوز الميقات ولم يحرم","answer":"الجواب: هذا فيه تفصيل: إذا كانت قدمت من مصر للعمرة فالواجب إحرامها من الميقات من ميقات أهل مصر وهو الجحفة -رابغ- إذا وازنته في البحر أو في الجو تحرم، وإن كان من طريق البر إذا وصلت إلى الجحفة من طريق الساحل تحرم وإن كان من طريق المدينة تحرم من ميقات المدينة هذا الواجب عليها، فإذا أحرمت من جدة يكون عليها دم يذبح في مكة للفقراء، وشاة تجزئ الضحية أو سبع بدنة أو سبع بقرة هذا هو الواجب عليها عن ترك الميقات، شاة واحدة يعني: جذع ضأن أو ثني معز يذبح في مكة للفقراء، أوسبع بدنة أوسبع بقرة يذبح في مكة للفقراء، هذا إذا كانت نوت العمرة من بلادها من مصر مثلاً، لكن ما أحرمت إلا من جدة تساهلت أو جهلت فهذا إحرامها صحيح من جدة وعمرتها صحيحة لكنها ناقصة تجبر بدم لأنها تركت الميقات الشرعي الذي يجب عليها، أما إن كانت جاءت من مصر ما نوت العمرة، جاءت لحاجة فلما وصلت جدة طرأ عليها العمرة وأنشأت العمرة من جديد نية جديدة فإحرامها صحيح من جدة وليس عليها شيء؛ لأنها لم تنو العمرة إلا من جدة لم تنشئها إلا من جدة، وهكذا مثلاً من جاء من الرياض إلى جدة أو من المدينة إلى جدة أو من الشام إلى جدة أو من غير ذلك وما عنده نية عمرة، فلما وصل جدة طرأ عليه وأنشأ العمرة وأحب أن يعتمر ليس عليه شيء، ميقات إحرامه صحيح لقول النبي ﷺ لما ذكر المواقيت قال: ومن كان دون ذلك -يعني دون المواقيت- فمهله من حيث أنشأ، حتى أهل مكة من مكة، يعني من كان دون المواقيت يكون إحرامه من حيث أنشأ النية نية الإحرام، جدة أو الشرايع أو التنعيم أو بالسلم أو غير ذلك إلا الحرم إذا كان في وسط الحرم يخرج إلى الحل، إذا طرأ عليه وهو في مكة أن يعتمر يخرج إلى الحل؛ لأن الرسول أمر عائشة أن تخرج إلى الحل عليه الصلاة والسلام لما أرادت العمرة قال: اخرجي إلى التنعيم التنعيم أدنى الحل، فإذا كان في مكة وطرأ عليه العمرة عن نفسه أو أبيه الميت أو أمه الميتة عن غيرهما من أمواته، أو عن أبيه العاجز لكبر سن أو مرض لا يرجى برؤه يخرج إلى الحل مثل عرفات مثل التنعيم تسمى مساجد عائشة مثل الجعرانة يعني خارج الأميال وراء الأميال من الحل ثم يلبي بالعمرة ويدخل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8325/حكم-من-قدم-للعمرة-وتجاوز-الميقات-ولم-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30706.mp3","categories":["الإحرام","المواقيت"]},{"id":10156,"question":"من يقول طالما أن الدم يسدد النقص وسوف أحرم من جدة، ما رأيكم؟","title":"حكم تعمد مجاوزة الميقات دون إحرام","answer":"الجواب: ما يجوز له يتعمد، بل يلزمه الميقات لأن الرسول ﷺ قال لما وقت المواقيت : هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد حجاً أو عمرة، وقال في اللفظ الآخر: يهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة معنى يهل هذا معناه الأمر، هو خبر بمعنى الأمر، وفي اللفظ الآخر: ليهل - باللام لام الأمر- ليهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة وأهل نجد من قرن وأهل اليمن من يلملم وأهل العراق من ذات عرق، فهذه مواقيت حددها الرسول ﷺ فعلى من أراد الحج أو العمرة أن يحرم منها إذا مرها وجوباً، إذا كان يريد الحج أو العمرة، أما إذا كان ما أراد إلا التجارة أو زيارة قريب أو صديق أو حاجات أخرى لا يلزمه الإحرام، لكنه يشرع له إلا إذا كان ما أدى العمرة عمرة الإسلام ولا حج حج الإسلام من مر عليها يلزمه الإحرام؛ لأنه وصل إلى مكة حينئذ استطاع، فإذا وصل إلى مكة وهو ما أدى عمرة الإسلام يحرم يلزمه الاعتمار، يعني يلزمه أن يحرم من الميقات بالعمرة لما من الله عليه بالاستطاعة أو جاء في وقت الحج يلزمه ذلك أيضاً إذا كان ما حج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8327/حكم-تعمد-مجاوزة-الميقات-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30708.mp3","categories":["الإحرام","المواقيت"]},{"id":10160,"question":"من يقول طالما أن الدم يسدد النقص وسوف أحرم من جدة، ما رأيكم؟","title":"حكم تعمد مجاوزة الميقات دون إحرام","answer":"الجواب: ما يجوز له يتعمد، بل يلزمه الميقات لأن الرسول ﷺ قال لما وقت المواقيت : هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد حجاً أو عمرة، وقال في اللفظ الآخر: يهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة معنى يهل هذا معناه الأمر، هو خبر بمعنى الأمر، وفي اللفظ الآخر: ليهل - باللام لام الأمر- ليهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة وأهل نجد من قرن وأهل اليمن من يلملم وأهل العراق من ذات عرق، فهذه مواقيت حددها الرسول ﷺ فعلى من أراد الحج أو العمرة أن يحرم منها إذا مرها وجوباً، إذا كان يريد الحج أو العمرة، أما إذا كان ما أراد إلا التجارة أو زيارة قريب أو صديق أو حاجات أخرى لا يلزمه الإحرام، لكنه يشرع له إلا إذا كان ما أدى العمرة عمرة الإسلام ولا حج حج الإسلام من مر عليها يلزمه الإحرام؛ لأنه وصل إلى مكة حينئذ استطاع، فإذا وصل إلى مكة وهو ما أدى عمرة الإسلام يحرم يلزمه الاعتمار، يعني يلزمه أن يحرم من الميقات بالعمرة لما من الله عليه بالاستطاعة أو جاء في وقت الحج يلزمه ذلك أيضاً إذا كان ما حج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8327/حكم-تعمد-مجاوزة-الميقات-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30708.mp3","categories":["الإحرام","المواقيت"]},{"id":10312,"question":"نعود في هذه الحلقة إلى رسالة المستمع (ح. م. ن) من الدوادمي، أخونا عرضنا جزءاً من أسئلته في حلقات مضت وفي هذه الحلقة بقي له جمع من الأسئلة في أحدها يقول: ما كيفية الإحرام من مكة؟ وماذا يقول المحرم عند النية؟ وهل يعمل كما يعمل عند الإحرام من الميقات؟ وهل يحرم للحج من مكة أم من الحل خارج مكة، جزاكم الله خيراً؟","title":"كيفية إحرام أهل مكة ومكان إحرامهم","answer":"الجواب: المحرم من مكة أو من الحل الذي قرب مكة أو من الميقات كل منهم يشرع له الغسل والتنظف والتطيب، ثم بعد ذلك يلبي بحجه أو عمرته، وإن كان هناك ما يستدعي قص شارب أو قلم ظفر فعل ذلك، إن كان له شارب طويل أو ظفر طويل استحب له أن يقص شاربه ويقلم أظفاره، ثم يلبي بقوله: اللهم لبيك حجاً إذا كان حج، أو اللهم لبيك عمرة بعد النية، بعدما ينوي بقلبه الدخول في الحج أو في العمرة ينوي بقلبه الدخول في الحج أو في العمرة ثم يلبي فيقول: اللهم لبيك عمرة، اللهم لبيك حجاً، كما فعله النبي عليه الصلاة والسلام، ولكن إذا كان للعمرة لابد يخرج من مكة لا يلبي في مكة، إذا كان أراد عمرة وهو ساكن في مكة أو قد حل من عمرة سابقة في مكة أو من حج في مكة وأراد العمرة فإنه يخرج إلى الحل ولا يلبي في مكة، يخرج إلى الحل إلى التنعيم المسمى مساجد عائشة أو إلى الجعرانة أو إلى عرفات أو غيرها من المواضع التي هي خارج الحرم في الحل، فينوي الدخول في العمرة ثم يلبي؛ لأن الرسول صلى الله عليه وسلم أمر عائشة لما أرادت العمرة أن تخرج إلى التنعيم إلى خارج الحرم، فذهب بها أخوها عبد الرحمن فأحرمت من التنعيم وهو خارج الحرم، وهكذا الناس مثلها من أراد أن يحرم بالعمرة فإنه يخرج من مكة إلى الحل، فينوي بقلبه الدخول للعمرة ثم يلبي سواء كان من أهلها أو ممن حل فيها من حج أو عمرة ثم أراد عمرة فإنه يخرج إلى الحل.\nأما الذي أتى من بلاده يريد العمرة أو يريد الحج، فإنه لابد أن يحرم من الميقات الذي يمر عليه، أن كان من طريق المدينة أحرم من ميقات المدينة إن كان من نجد أو الطائف أحرم من السيل ميقات أهل نجد، إن كان من طريق اليمن أحرم من ميقات اليمن، إن كان من طريق المغرب أو مصر أو الشام أحرم من رابغ إذا كان جاء من طريق الساحل أحرم من رابغ إذا وازنه، إن كان من العراق أحرم من ميقات العراق، وهو ذات عرق ويسمى الضريبة، سواء كان أتى لعمرة أو حج؛ لأن النبي ﷺ قد وقت المواقيت للناس وقال: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج أو العمرة، ثم قال ﷺ: ومن كان دون ذلك فمهله من حيث أنشأ حتى أهل مكة من مكة، فمن كان دون المواقيت إذا أراد العمرة أو الحج يحرم من مكانه، أهل جدة من جدة، وأهل الشرايع من الشرايع وأهل النجيم من النجيمة وأهل أم السلم من أم السلم وهكذا، كل إنسان دون المواقيت يحرم من مكانه في الحج والعمرة، حتى أهل مكة إذا أرادوا الحج يحرموا من مكة.\nوهكذا من قدم مكة من غير أهلها، قدمها للتجارة أو لزيارة الأقارب أو لأغراض أخرى ما أراد حجاً ولا أراد عمرة ثم بدا له أن يحج وقت الحج يحرم من مكة، والحمد لله.\nأما العمرة فإنه كما تقدم يخرج إلى الحل، إذا أراد عمرة وهو في مكة يخرج إلى الحل ويحرم من الحل، كما تقدم من حديث عائشة رضي الله عنها أن النبي ﷺ أمرها لما أرادت العمرة أن تخرج إلى الحل، فخرجت ومعها أخوها عبد الرحمن وأحرمت من التنعيم، والتنعيم خارج الحرم ويسمى الآن تسميه الناس اليوم مساجد عائشة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8476/كيفية-احرام-اهل-مكة-ومكان-احرامهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31302.mp3","categories":["الإحرام"]},{"id":10541,"question":"هذا سوداني مقيم بالمملكة العربية السعودية، يقول: سماحة الشيخ بإذن الله ناوي أن أؤدي فريضة الحج هذا العام، ولكن بيدي اليمنى عيب أو كسر واضح وأكره أن يراه الناس، علماً بأنني مؤمن إيمانًا كاملًا بالقضاء، فهل يجوز لي عند الإحرام أن أغطي الجزء الأيمن من يدي بقطعة وإن أمكن بجزء من الإحرام نفسه أفيدوني بذلك؟","title":"حكم تغطية اليد المعيبة للمحرم","answer":"الجواب: لا حرج في ذلك، غطه بقطعة من الإحرام، أما بفعل شيء خاص لا، لكن إذا جاء طرف الإحرام على يده لا حرج الحمد لله، والأمر سهل، ولو رأى الناس الكسر الحمد لله على كل حال، يدعون له، المقصود أنه لا بأس أن يضع طرف الإحرام على محل الكسر. نعم.\nالمقدم: طيب.","link":"https://binbaz.org.sa/fatwas/8716/حكم-تغطية-اليد-المعيبة-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28413.mp3","categories":["الإحرام"]},{"id":10665,"question":"من منطقة سدير جلاجل، المستمع سليمان بن إبراهيم الوكيل، بعث يسأل ويقول: رجل قدم من مصر بقصد العمرة والعمل عن طريق الجو، وعند محاذاة الميقات إذا ملابس إحرامه داخل العفش، فنزل في المطار وأحرم من جدة، فهل عليه شيء؟ وما حكم عمرته؟ نرجو الإفادة والتوجيه.","title":"حكم من ركب جواً وتجاوز الميقات دون أن يحرم للعمرة","answer":"الجواب: نعم، عليه دم لأنه ترك الميقات وعمرته صحيحة، وعليه دم لترك الإحرام من الميقات، ولو أحرم في ثيابه من أول إحرامه، أحرم في ثيابه بمخيطه وكشف رأسه ونوى الدخول في الإحرام وهو في الميقات كان ذلك هو الواجب عليه، ثم يلبس ملابس الإحرام بعد ذلك، ويكون عليه لبقاء المخيط صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة، هذه الثلاث، إما صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة، لكونه استدام المخيط، في الميقات وبعده، حتى يلبس ثياب الإحرام، وهذا هو الواجب على الذي وصل الميقات ولم يجد ملابس الإحرام يحرم في ثيابه العادية، ينوي الإحرام في ثيابه ويلبي وهو معذور في هذه الحالة، وإذا وجد الملابس بعد ذلك، خلع المخيط ولبس ملابس الإحرام، لكن يكشف رأسه، لأن كشف الرأس متيسر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8846/حكم-من-ركب-جوا-وتجاوز-الميقات-دون-ان-يحرم-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32912.mp3","categories":["الإحرام"]},{"id":10673,"question":"من منطقة سدير جلاجل، المستمع سليمان بن إبراهيم الوكيل، بعث يسأل ويقول: رجل قدم من مصر بقصد العمرة والعمل عن طريق الجو، وعند محاذاة الميقات إذا ملابس إحرامه داخل العفش، فنزل في المطار وأحرم من جدة، فهل عليه شيء؟ وما حكم عمرته؟ نرجو الإفادة والتوجيه.","title":"حكم من ركب جواً وتجاوز الميقات دون أن يحرم للعمرة","answer":"الجواب: نعم، عليه دم لأنه ترك الميقات وعمرته صحيحة، وعليه دم لترك الإحرام من الميقات، ولو أحرم في ثيابه من أول إحرامه، أحرم في ثيابه بمخيطه وكشف رأسه ونوى الدخول في الإحرام وهو في الميقات كان ذلك هو الواجب عليه، ثم يلبس ملابس الإحرام بعد ذلك، ويكون عليه لبقاء المخيط صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة، هذه الثلاث، إما صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة، لكونه استدام المخيط، في الميقات وبعده، حتى يلبس ثياب الإحرام، وهذا هو الواجب على الذي وصل الميقات ولم يجد ملابس الإحرام يحرم في ثيابه العادية، ينوي الإحرام في ثيابه ويلبي وهو معذور في هذه الحالة، وإذا وجد الملابس بعد ذلك، خلع المخيط ولبس ملابس الإحرام، لكن يكشف رأسه، لأن كشف الرأس متيسر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8846/حكم-من-ركب-جوا-وتجاوز-الميقات-دون-ان-يحرم-للعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32912.mp3","categories":["الإحرام"]},{"id":10749,"question":"من الأفلاج المستمع سعد راشد بعث برسالة يقول فيها: ذهبت إلى مكة المكرمة بنية الحج والعمرة، وأحرمت من السيل ثم أديت جميع الشعائر المفروضة، وبعد أن طفت طواف الوداع ذهبت إلى المدينة المنورة للسلام على رسول الله ﷺ، ثم عدت إلى مكة المكرمة دون أن أحرم، فهل علي إثم في هذا وهل تلزمني كفارة؟ أرجو الإفادة جزاكم الله خيراً.","title":"حكم تجاوز الميقات دون إحرام، وشد الرحال لقبر النبي","answer":"الجواب: إذا كنت رجعت من المدينة بغير نية العمرة فلا شيء عليك، أما إذا كنت ناوياً العمرة فالواجب عليك أن تحرم من ميقات المدينة، فإذا لم تحرم من ميقات المدينة وأنت ناوي العمرة فعليك دم، إذا أحرمت من مكة أو من جدة أو نحو ذلك؛ لأنك تركت الميقات، أما إذا رجعت من دون إحرام ولا قصدت عمرة فلا شيء عليك، أو قصدت عمرة ولا أحرمت فعليك أن ترجع إلى الميقات وتحرم من الميقات إذا عزمت على العمرة، وإلا فلا عمرة عليك.\nولكن سفرك إلى المدينة من أجل السلام على الرسول ﷺ هذا ليس بمشروع، المشروع أن تقصد المسجد ثم يكون السلام تبعاً لذلك، هكذا جاءت الأحاديث عن رسول الله عليه الصلاة والسلام، في الحديث الصحيح يقول عليه الصلاة والسلام: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، ما قال: لا تشد للسلام إلى كذا، قال: إلا إلى ثلاثة مساجد، فسمى المساجد.\nفالمشروع: أن يكون شد الرحال لقصد المساجد، فإذا جئت المسجد النبوي سلمت على الرسول ﷺ وعلى صاحبيه، وشرع لك أيضاً أن تزور البقيع وتسلم على أهل البقيع، كما يشرع لك أيضاً أن تزور مسجد قباء وتصلي فيه ركعتين، هذه كلها مشروعة لمن زار المدينة، لكن يكون القصد الأول في الرحلة الصلاة في المسجد النبوي، وإذا أردت مع ذلك السلام على الرسول عليه الصلاة والسلام فلا بأس يكون تبعاً لزيارة المسجد، أما أن تكون الرحلة أصلها كله أصلها للسلام على الرسول ﷺ وزيارة القبر هذا غير مشروع، ولكن تكون الرحلة لقصد المسجد، ولا بأس أن يكون معها وتضم إليها زيارة الرسول ﷺ والسلام عليه تبعاً للمسجد، ولكن الشيء الذي لا يصلح أن تكون الزيارة للقبر فقط والسلام على الرسول ﷺ.\nفينبغي التنبه لهذا؛ لأن الرسول عليه السلام قال: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، فمعناه: أنه لا تشد الرحال لقصد زيارة القبور لا قبر النبي ﷺ ولا غيره، وإنما تشد لقصد هذه المساجد الثلاثة، وزيارة القبور تكون تبعاً إذا أتى المدينة زار قبر النبي ﷺ وسلم عليه وسلم على صاحبيه، شرع له أن يزور البقيع، يزور أحد الشهداء في أحد يسلم عليهم، تبعاً لهذه الزيارة للمسجد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8923/حكم-تجاوز-الميقات-دون-احرام-وشد-الرحال-لقبر-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34606.mp3","categories":["الإحرام","المواقيت"]},{"id":11069,"question":"هذا السائل أبو عبدالله يقول: اختلف مجموعة من الإخوة حول هذه المسألة إذا كان لدى الإنسان مهمة عمل -مثلًا- في جدة انتدب إليها، وهو مقيد بأيام محدودة، وبنيته وهو في الرياض يقول: إذا خلصت من هذه المهمة سوف آخذ عمرة، فإذا أنهى مهمته المكلف بها، وأحرم من جدة، فهل يلزمه شيء؟","title":"حكم من نوى العمرة وجاوز الميقات دون أن يحرم","answer":"الجواب:  نعم يلزمه دم؛ لأنه ناوي العمرة من الأصل فيلزمه أن يذهب إلى الميقات الذي مر عليه، ويحرم من الميقات إذا فرغ من عمله، فإن أحرم -مثلًا- من جدة وذهب إلى مكة، فعليه دم؛ لأنه ترك الميقات. أما لو كان ما نوى شيئًا في الطريق، ولا في بلده، إنما لما انتهى عمله من جدة طرأ عليه الإحرام فلا بأس يحرم من جدة، لقوله ﷺ: ومن كان دون ذلك فمهَله من حيث أنشأ، حتى أهل مكة من مكة، أما ما دام وقد أسس النية في بلده أنه يعتمر فعليه أن يرجع إلى الميقات. نعم.","link":"https://binbaz.org.sa/fatwas/9247/حكم-من-نوى-العمرة-وجاوز-الميقات-دون-ان-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28817.mp3","categories":["الإحرام"]},{"id":11622,"question":"ماذا تلبس المرأة إذا أرادت الحج أو العمرة؟","title":"ما تلبسه المرأة وهي محرمة","answer":"الجواب:  وقت الإحرام تغطي وجهها بغير البرقع، بخمار كالعادة في أسواق المسلمين، نعم، الخمار يكفي، ولا حاجة إلى برقع، لا يجوز البرقع، حتى تحل من إحرامها، وهكذا يداها تسترهما بغير قفازين، لا تلبس القفازين، ولا البرقع في حال الإحرام للحج أو العمرة حتى تحل، لقوله ﷺ للمحرمة: لا تنتقب، ولا تلبس القفازين. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9799/ما-تلبسه-المراة-وهي-محرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38810.mp3","categories":["الإحرام"]},{"id":11717,"question":"يسأل سماحتكم -جزاكم الله خيرًا- عن النسك الثلاثة أيها أفضل، القران والتمتع والإفراد؟","title":"أفضل أنواع النسك في الحج وصفة كل نوع","answer":"الجواب:  أفضلها التمتع كما أمر به النبي ﷺ في حق من قدم بعد رمضان .. أفضلها التمتع، وهو أن يحرم بالعمرة من الميقات الذي يمر عليه، ثم يطوف ويسعى ويقصر ويحل، ويبقى حتى يأتي وقت الحج، فإذا جاء اليوم الثامن من ذي الحجة وهو يوم التروية؛ لبى بالحج، وذهب إلى منى، ثم عرفات ووقف بعرفات يوم عرفة بعد صلاة الظهر والعصر إلى غروب الشمس، ثم ذهب إلى مزدلفة، وبات بها، ووقف بها بعد الفجر إلى أن يسفر جدًا، إلى الإسفار، ثم ينصرف إلى منى إلى آخره. فالمقصود: إن التمتع هو الأفضل، وهو يشتمل على طواف وسعي للعمرة، وعلى طواف وسعي بعد الحج للحج، وباقي أعمالها أعمال الحجاج كلهم، أعمال المفرد والقارن، هذا هو الأفضل. وإذا أحرم بالحج وحده، أو بالحج والعمرة جميعًا؛ فلا حرج في ذلك، لكن الأفضل أنه يلبي بالعمرة، ويطوف ويسعى ويقصر ويحل إلا إن كان قد ساق معه هديًا، جاء معه إبل أو غنم أو بقر يذبحها في مكة؛ فهذا يحرم بالحج والعمرة جميعًا، هذا الأفضل، يلبي بالحج والعمرة جميعًا ... قارنًا، ويطوف ويسعى إذا قدم، ويبقى على إحرامه، فإذا جاء بعد الحج يوم العيد، أو بعده طاف فقط طواف الإفاضة يكفيه، وإذا رمى الجمار، وأراد السفر؛ طاف للوداع، هذا يسمى قارنًا. ومثله المفرد الذي أحرم بالحج وحده عمله عمل القارن، إذا قدم مكة يطوف ويسعى ويبقى على إحرامه، ثم بعد نزوله من عرفات ومزدلفة يطوف فقط.. السعي الأول وإن أخر السعي إلى بعد العيد وسعاه مع طواف القدوم كذلك كفى. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9897/افضل-انواع-النسك-في-الحج-وصفة-كل-نوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39210.mp3","categories":["الإحرام"]},{"id":12343,"question":"أحد الإخوة المستمعين يرجو من سماحتكم التوجيه في بعض الأمور يقول: تركي ناعم يقول: أنا كثير المرور على مكة المكرمة، وأحيانًا أمر البيت الشريف، وأصلي فيه، وأطوف فقط بدون نية العمرة بثوبي، وأحيانًا أصلي فقط، ولا أطوف، فهل هذا جائز، أم يلزمني الإحرام كلما نويت أمر البيت الشريف، علمًا بأنني قد حجيت مرتين، واعتمرت عدة مرات؟","title":"حكم دخول مكة بغير إحرام لمن يتكرر دخوله إليها","answer":"الجواب:  كل هذا جائز، لا بأس أن يأتي الإنسان إلى مكة بغير إحرام، ويطوف أو يصلي بدون طواف، كل هذا الأمر فيه واسع، إنما تجب العمرة والحج مرة واحدة، في العمر مرة، أو بالنذر إذا نذره. أما إن كان قد أدى فريضة الحج والعمرة، ولم ينذر؛ فإنه يدخل مكة بدون إحرام، ولا بأس على الصحيح؛ لقوله ﷺ لما وقت المواقيت، قال: هن لهن، ولمن أتى عليهن من غير أهلهن، ممن أراد الحج والعمرة فدل ذلك على أن من لم يرد؛ لا شيء عليه، إذا مر عليها، ولم يرد حجًا، ولا عمرة، يدخل كسائر الناس من دون إحرام، فإن شاء صلى في الحرم، أو صلى في بعض المساجد الأخرى، وإن شاء طاف وترك الطواف، الأمر في هذا واسع. لكن ينبغي له أن يغتنم الفرصة، يشرع له أن يطوف، وأن يصلي في المسجد الحرام مع الناس، اغتنامًا للفرصة، والفضل العظيم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10546/حكم-دخول-مكة-بغير-احرام-لمن-يتكرر-دخوله-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39905.mp3","categories":["الإحرام"]},{"id":12401,"question":"يقول: شخص قادم من لندن بالطائرة، ونزل في جدة، ولم يحرم قبل بدء سفره، ولم ينبهه عمال الطائرة عند المرور من الميقات، فكيف يحرم؟ وإذا نزل بجدة بدون إحرام، فماذا يلزمه؟","title":"حكم من نزل بالطائرة في جدة ولم يحرم مع محاذاة الميقات","answer":"الجواب:  إذا كان جاء من طريق الساحل من طريق البحر؛ يرجع إلى رابغ، ويحرم من رابغ، أما إن كان جاء من طريق المدينة؛ فليرجع إلى ميقات المدينة، وأما إذا كان ما يعلم محاذاة أي ميقات، الطريق الذي جاء من جهة الغرب، لا يعلم أنه حاذى لا ميقات رابغ، ولا غيره؛ فيحرم من جدة، ولكن إذا كانت الطائرة تحاذي رابغًا، تحاذي الجحفة؛ فإحرامه من رابغ، يرجع إليها على السيارات، ويحرم من رابغ.  وهكذا من جاء من طريق البحر، إذا حاذى رابغًا؛ يحرم من رابغ وهو في البحر، وهكذا في الجو إذا حاذى رابغًا في الجو، أو حاذى الحليفة إن كان من طريق المدينة يحرم من محاذاته في الجو، وإذا كان الملاح، ملاح الطائرة يعلم أنه ما حاذى رابغًا، ولا حاذى ميقاتًا آخر، إنما جاء من طريق يعني: غرب صامد، ما حاذى شيئًا، فميقاته جدة، إذا لم يحاذ ميقاتًا قبل ذلك، نعم. المقدم: بارك الله فيكم، الواقع هذه معلومة جديدة سماحة الشيخ -جزاكم الله خيرًا- لأن هناك كثيرًا من الناس يقولون: لماذا يحرم البعض من جدة؟ إذًا يحرم من جدة......؟ الشيخ: من لم يحاذ ميقاتًا قبل وصوله إليها في الجو، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10606/حكم-من-نزل-بالطاىرة-في-جدة-ولم-يحرم-مع-محاذاة-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45506.mp3","categories":["الإحرام","المواقيت"]},{"id":12402,"question":"المستمع عبده علي محمد واصل من ينبع البحر، المنطقة الصناعية، بعث برسالة ضمنها جمعًا من الأسئلة، يقول في أحدها: هل يجوز دخول مكة بدون إحرام لسبب غير هام، أو لمجرد الطواف؟ وإذا كان لا يجوز ذلك فمن هم الذين يجوز لهم الدخول في مكة من غير إحرام؟","title":"حكم دخول مكة لزيارة أقارب أو حاجة دون إحرام","answer":"الجواب:  إذا أراد مكة للطواف، أو لزيارة بعض أقاربه أو أصدقائه، أو لحاجة أخرى؛ لا يلزمه إحرام، لا حرج عليه؛ لأن الرسول -عليه الصلاة والسلام- قال -لما وقت مواقيت قال-: هن لهن، ولمن أتى عليهن، من غير أهلهنن ممن أراد الحج والعمرة. هذا شرط، فلا يلزمه الإحرام إلا إذا أراد حجًا، أو عمرة، أما من جاء إلى مكة للتجارة، أو لزيارة بعض أقاربهن، أو أصدقائه، أو لمجرد أن يصلي في المسجد الحرام، ويطوف؛ فلا إحرام عليه، ولا حرج عليه في ذلك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10607/حكم-دخول-مكة-لزيارة-اقارب-او-حاجة-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45507.mp3","categories":["الإحرام"]},{"id":12592,"question":"ما حكم من خرج خارج الحرم بعد الطواف والسعي للعمرة؛ ليحلق عند الحلاقين قبل أن يتحلل من إحرامه؟","title":"حكم من خرج من الحرم للحلق بعد الطواف والسعي","answer":"الجواب:  لا حرج في هذه الملابس هو متحلل إذا فَعل فِعل المتحللين، ولو بقي عليه الإزار والرداء، فإذا طاف، وسعى، وخرج، وقصر، أو حلق لا بأس؛ لأن عليه أن يكمل عمرته قبل أن يخلع الملابس، قبل أن يلبس المخيط. فالمقصود: أنه يكمل بعد الطواف والسعي، يكمل الحلق والتقصير قبل أن يلبس المخيط، ولو حلق رأسه، أو قصره، وبقي على حاله في الإزار والرداء يومًا، أو يومين، أو أكثر؛ فلا بأس بذلك؛ لأنه لباس شرعي، لكن ليس فيه بأس، ولو استمر فيه؛ كان هذا من لباس العرب، كان الرسول يلبسه -عليه الصلاة والسلام- يلبس الإزار والرداء، هو لباس شرعي ليس فيه شيء، لكن المحرم يبقى في هذا اللباس حتى ينتهي من إحرامه، لا يلبس المخيط، إنما يبقى في الإزار والرداء إذا كان ذكرًا؛ حتى يكمل الطواف والسعي، أو الحلق والتقصير في العمرة، وفي الحج حتى يرمي الجمرة، جمرة العقبة، ويحلق، أو يقصر، أو يطوف، ثم يتحلل، بلبس المخيط، ثم يكمل مناسك حجه.  وإذا فعل الثلاث؛ أحل من كل شيء، إذا رمى وحلق، أو قصر وطاف، وسعى إن كان عليه سعي؛ تم حله؛ صار حلًا كاملًا، وإذا فعل اثنين من هذه الثلاثة: بأن رمى وحلق أو قصر، أو رمى وطاف، أو طاف أو حلق وقصر؛ حل التحلل الأول، وبقي عليه التحلل الثاني إذا كمل. نعم. المقدم: جزاكم الله خيرًا، إنما بالنسبة للمعتمر لا يشترط أن يخلع الملابس في الإحلال ...؟  الشيخ: لا يجوز له لبس المخيط حتى يكمل، إذا طاف وسعى يبقى عليه الإزار والرداء، أو الإزار فقط حتى يحلق أو يقصر، ثم بعد هذا إذا شاء يخلع الملابس، ويلبس المخيط القميص، أو يغطي رأسه؛ فلا بأس، لكن ليس له أن يغطي رأسه، وليس له أن يلبس المخيط حتى يكمل نسك العمرة: من طواف، وسعي، وتقصير، أو حلق إذا كان رجلًا.  أما إن كان امرأة فالمرأة يباح لها لبس المخيط؛ لأنها عورة، ولكن لا تنتقب، ولا تلبس القفازين حتى تكمل مناسك العمرة: بالطواف، والسعي، والتقصير، فإذا طافت وسعت، وقصرت؛ حلت، يجوز لها الطيب، وقص الشعر، قلم الأظفار، الانتقاب، لبس القفازين؛ لأنها حلت بالطواف والسعي والتقصير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10803/حكم-من-خرج-من-الحرم-للحلق-بعد-الطواف-والسعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41306.mp3","categories":["الإحرام"]},{"id":13044,"question":"يقول هذا السائل: أيهما أفضل -يا سماحة الشيخ- ثواب الإفراد، أم القران، أم التمتع؟","title":"أفضل مناسك الحج","answer":"الجواب:  التمتع أفضل، كونه يدخل بعمرة، يطوف ويسعى ويقصر أو يحلق ويحل، ثم يحرم بالحج يوم الثامن، هذا أفضل، هذا التمتع الذي أمر به النبي ﷺ الصحابة -رضي الله عنهم- يقال له: التمتع، كونه يحرم بالعمرة، ويطوف، ويسعى ويقصر ويحل. وإن كان أحرم بالحج، أو بالحج والعمرة يحل أيضًا، يفسخهما إلى أربع، يعني: ولو كان لبى بالحج مفردًا، أو بالحج والعمرة جميعًا وهو قارن السنة له أنه يطوف ويسعى ويقصر ويحل يجعلها عمرة، كما أمر النبي ﷺ الصحابة بذلك إلا من ساق الهدي، إلا الذي جاء معه هدي من بلاده، أو من الطريق إبل أو بقر أو غنم، يريد التقرب بها إلى الله في منى؛ هذا لا يحل، يبقى على إحرامه حتى يحج. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11261/افضل-مناسك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50504.mp3","categories":["الإحرام"]},{"id":13236,"question":"السائل عصام آدم مقيم بالمملكة يقول في هذا  أديت فريضة الحج، وأنا محرم في منى، وبتنا في منى، وحصل لي حدث، واغتسلت، وذهبت في الصباح إلى عرفة، هل حجتي صحيحة، أم يلزمني شيء؟","title":"حكم من احتلم وهو محرم","answer":"الجواب:  إذا كان أراد بهذا أنه احتلم؛ فلا يضره ذلك، الاحتلام ما هو باختياره، إذا احتلم، ورأى المني ما يضر حجه، عليه أن يغتسل، والحمد لله، وحجه صحيح. الممنوع أن يتعمد جماع الزوجة، هذا الممنوع، أما كونه يحتلم في الليل، أو في النهار، وهو حاج، أو في رمضان، لا يضره ذلك، لا يضر حجه، ولا صومه؛ لأنه ليس باختياره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11518/حكم-من-احتلم-وهو-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52018.mp3","categories":["الإحرام"]},{"id":14141,"question":"في ثاني أسئلته يقول هذا السائل سماحة الشيخ: المحرم هل يجب أن يغتسل قبل إحرامه بالحج أو العمرة؟","title":"حكم الغسل قبل الإحرام","answer":"الجواب: سنة الاغتسال، سنة أن يغتسل قبل إحرامه وليس بواجب، لو أحرم ولم يغتسل فلا حرج، لكن جاء عنه ﷺ أنه اغتسل عند إحرامه، وأن من السنة الاغتسال عند الإحرام، هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/12582/حكم-الغسل-قبل-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54606.mp3","categories":["الإحرام"]},{"id":14156,"question":"تسأل أختنا سؤالًا آخر وتقول: هل يجوز للمرأة الجمع بين صيام ستة أيام من شوال وقضاء ما عليها من رمضان في هذه الأيام الستة بنية القضاء والأجر معًا؟ أم لا بد من القضاء أولًا ثم صيام ستة أيام من شوال؟","title":"هل يجوز صيام ست من شوال بنية القضاء والتنفل؟","answer":"الجواب: نعم تبدأ بالقضاء ثم تصوم الست إذا أردت، الست نافلة فإذا قضت في شوال ما عليها ثم صامت الست في شوال فهذا خير عظيم، وأما أن تصوم الست بنية القضاء والست فلا يظهر لنا أنه يحصل لها بذلك أجر الست، فالست تحتاج إلى نية خاصة في أيام مخصوصة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12597/هل-يجوز-صيام-ست-من-شوال-بنية-القضاء-والتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48506.mp3","categories":["النية في الصيام","الإحرام"]},{"id":14213,"question":"يقول: هل النية عند الإحرام ضرورية أم لا؟","title":"حكم النية عند الإحرام","answer":"الجواب: لا بد من النية، الأعمال بالنيات، يقول ﷺ: إنما الأعمال بالنيات فلابد أن ينوي الحج أو العمرة عند الإحرام من الميقات، وهكذا في مكة إذا كان يوم الثامن عند ذهابه إلى منى لابد ينوي الحج أيضًا ويحرم، الأعمال بالنيات.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12663/حكم-النية-عند-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54814.mp3","categories":["الإحرام"]},{"id":14744,"question":"السائلة من ينبع تقول في هذا  والدتي حجت، وأحرمت بملابس هدية، فهل يلزمها شيء الآن؟","title":"حكم الإحرام بملابس أهديت إليها","answer":"الجواب: لا حرج في ذلك، سواء أحرمت في ملابس أهديت إليها، أو في ملابس أخرى، ما دامت ملابس مباحة، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13237/حكم-الاحرام-بملابس-اهديت-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56102.mp3","categories":["الإحرام","الحيض والنفاس","قضايا المرأة"]},{"id":14803,"question":"المستمع: محمد صالح أبو العظام، من مصر، بعث برسالة يقول فيها: قبل ثمان سنوات كنت أعمل في الرياض، وتلقيت خبرًا من والدتي بأنها ستؤدي فريضة الحج، وعلي أن أستقبلها بمطار جدة، وبالفعل ذهبت لاستقبالها، ولأداء فريضة الحج معها، وقبل السفر سألت بعض الإخوة عن كيفية الإحرام؟فقالوا لي: تحرم من جدة، ولضيق الوقت لم أسأل غيرهم، فذهبت واستقبلت الوالدة، وأحرمت من جدة، وبعدها انتقل عملي إلى جدة، فحججت -ولله الحمد- مرتين، مرةً عن والدي، ومرةً عن جدي، ولكن ما يشغل بالي هو إحرامي من جدة في المرة الأولى، وأنا قادم من الرياض، فهل يكون حجي صحيحًا أم لا؟ وإذا كان غير صحيح هل علي أن أعيده، أم علي كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم حج من تجاوز الميقات وأحرم من جدة","answer":"الجواب: الحج صحيح، ولكن عليك دم واحد فدية؛ لأنك تركت الميقات، وهو وادي قرن، الذي يحرم منه أهل نجد، وأهل الطائف؛ لأنك حين خرجت من الديار قاصدًا الحج مع والدتك، فالواجب عليك الإحرام من ميقات أهل نجد، وهو السيل، وادي قرن، فعليك دم عن ترك ذلك، يذبح في مكة، وحجك صحيح، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا صادف أنه عاشر أهله -سماحة الشيخ- قبل أن يقدم هذا الهدي، فهل تنصحونه؟\nالشيخ: لا يضر، لا يضر، لا، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13310/حكم-حج-من-تجاوز-الميقات-واحرم-من-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64211.mp3","categories":["الإحرام","المواقيت"]},{"id":14811,"question":"المستمع: محمد صالح أبو العظام، من مصر، بعث برسالة يقول فيها: قبل ثمان سنوات كنت أعمل في الرياض، وتلقيت خبرًا من والدتي بأنها ستؤدي فريضة الحج، وعلي أن أستقبلها بمطار جدة، وبالفعل ذهبت لاستقبالها، ولأداء فريضة الحج معها، وقبل السفر سألت بعض الإخوة عن كيفية الإحرام؟فقالوا لي: تحرم من جدة، ولضيق الوقت لم أسأل غيرهم، فذهبت واستقبلت الوالدة، وأحرمت من جدة، وبعدها انتقل عملي إلى جدة، فحججت -ولله الحمد- مرتين، مرةً عن والدي، ومرةً عن جدي، ولكن ما يشغل بالي هو إحرامي من جدة في المرة الأولى، وأنا قادم من الرياض، فهل يكون حجي صحيحًا أم لا؟ وإذا كان غير صحيح هل علي أن أعيده، أم علي كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم حج من تجاوز الميقات وأحرم من جدة","answer":"الجواب: الحج صحيح، ولكن عليك دم واحد فدية؛ لأنك تركت الميقات، وهو وادي قرن، الذي يحرم منه أهل نجد، وأهل الطائف؛ لأنك حين خرجت من الديار قاصدًا الحج مع والدتك، فالواجب عليك الإحرام من ميقات أهل نجد، وهو السيل، وادي قرن، فعليك دم عن ترك ذلك، يذبح في مكة، وحجك صحيح، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا صادف أنه عاشر أهله -سماحة الشيخ- قبل أن يقدم هذا الهدي، فهل تنصحونه؟\nالشيخ: لا يضر، لا يضر، لا، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13310/حكم-حج-من-تجاوز-الميقات-واحرم-من-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64211.mp3","categories":["الإحرام","المواقيت"]},{"id":14816,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من المدينة المنورة، وادي القرع، وباعثها المستمع عبدالمعز عبدالباقي العسال، له جمع من الأسئلة، في أحد أسئلته يقول:ذهبت أنا وزوجتي لعمل العمرة في سيارة كانت متجهة من مكاننا في قرية تابعة للمدينة المنورة، تبعد عن رابغ تسعين كيلو متر عن الميقات، متجهة إلى جدة، عن طريق رابغ، وليست متجهة أصلًا إلى مكة المكرمة؛ ولما وصلنا الميقات في رابغ، قال لنا السائق: أحرموا من جدة بدلًا من أن تحرموا من الميقات وتدخلون معنا جدة، ففعلنا، ولم نحرم من الميقات.الشيخ: أعد أعد.المقدم: يقول: ذهبت أنا وزوجتي لعمل العمرة في سيارة كانت متجهة من مكاننا في قرية، تابعة للمدينة المنورة، تبعد عن رابغ تسعين كيلو متر عن الميقات، متجهة إلى جدة، عن طريق رابغ، وليست متجهة أصلًا إلى مكة المكرمة؛ ولما وصلنا الميقات في رابغ قال لنا السائق: أحرموا من جدة بدلًا من أن تحرموا من الميقات، وتدخلون معنا جدة، ففعلنا ولم نحرم من الميقات، وأحرمنا من جدة، وذهبنا في نفس الوقت إلى مكة، وعملنا العمرة، فما مدى صحة العمرة وصحة الإحرام؟ أفيدونا، جزاكم الله كل خير.","title":"حكم عمرة من أحرم من غير الميقات","answer":"الجواب: الإحرام صحيح، والعمرة صحيحة، ولكنها ناقصة؛ لأنكم تركتم الواجب، وهو الإحرام من الميقات، فعليكم دم ذبيحة واحدة عن كل واحد منكما تذبح في مكة للفقراء كالضحية، يعني: ذبيحة تجزي في الأضحية جذع ضأن، أو ثني معز، أو سبع بدنة، أو سبع بقرة، عن ترك الميقات.  أما العمرة فهي صحيحة، والحمد لله، والإحرام صحيح، لكن فيها نقص، عمرة ناقصة؛ بسبب الإخلال بالواجب وهو الإحرام من الميقات، تقبل الله من الجميع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13313/حكم-عمرة-من-احرم-من-غير-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64302.mp3","categories":["الإحرام","المواقيت"]},{"id":14947,"question":"سؤاله الأخير يقول: المسافر بالطائرة الذي لم يحرم إلا من جدة؛ لأن ملابس إحرامه كانت في الحقيبة والحقيبة في مخزن الأمتعة بالطائرة، وكان يعتقد أن الإحرام لا يصح إلا بملابس الإحرام، ما الذي عليه؟ جزاكم الله عنا خير الجزاء.","title":"ما حكم من أحرم من جدة لعدم توفر ملابس الإحرام؟","answer":"الجواب: الذي جاوز الميقات، وأتى جدة، وأحرم منها، عليه دم عند أكثر أهل العلم؛ لكونه ترك واجبًا عليه لعمرته أو حجه؛ ولقول ابن عباس -رضي الله تعالى عنهما-: «من ترك نسكًا، أو نسيه فليرق دمًا» يروى مرفوعًا إلى النبي ﷺ، ويروى موقوفًا عليه على ابن عباس، وهو أصح، لكنه في حكم الرفع؛ لأن مثل هذا الكلام تأسيس قاعدة شرعية، لا يقال من جهة الرأي؛ ولهذا أخذ به الجمهور، وقالوا: على مثل هذا دم؛ لأنه ترك واجبًا. ثم ينبغي لمثل هذا أن ينتبه، فإذا جاء وقت الإحرام وليس معه ملابس الإحرام يحرم فيما عليه، إن كان عليه سراويل كفت السراويل، ونزع القميص والعمامة، وجعل بعضها على كتفيه يكفي، ويبقى السراويل عليه، ولا عليه شيء، وإن شاء اتخذ قميصه إزارًا حتى يصل إلى جدة، وكفى، وأزال ما على رأسه. وبهذا يسلم من تجاوز الميقات بغير إحرام، ويسلم من الفدية، فإن أحرم على حاله فهو أولى، إن أحرم على حاله، ولم يغير فهو أولى من التأخير، لكن إذا أمكنه أن يخلع القميص، ويبقى عليه السراويل إذا كان عليه سراويل، فهذا هو الواجب عليه، يبقى في السراويل، ويزيل القميص والعمامة التي على رأسه، وهو مخير: إن شاء وضع القميص كذا على كتفيه، أو عمامته على كتفيه تقوم مقام الرداء، وإن شاء ترك، فإذا وصل إلى جدة أمكنه أن يغير، فإن لم يفعل؛ لزمه أن يحرم ولو على ثيابه هذه التي هي عليه، لزمه أن يحرم، وإذا وصل مكة، فدى بأحد ثلاثة: صيام ثلاثة أيام، أو إطعام ستة مساكين، أو ذبح شاة، كما أفتى النبي ﷺ بذلك كعب بن عجرة لما حلق رأسه. هذا الذي أحرم في ثيابه المخيطة وعمامته، ولم يخلعها؛ عليه أن يفدي بإحدى هذه الثلاث؛ إما صيام ثلاثة أيام، وإما إطعام ستة مساكين لكل مسكين نصف صاع من التمر، أو من الأرز، أو غيرهما من قوت البلد، وإما ذبح شاة، هذا عن المخيط، ومثل ذلك عن تغطية الرأس إذا لم يكشف رأسه، فيكون عليه كفارتان: إحداهما عن تغطية الرأس إذا لم يكشفه، والثانية عن المخيط الذي عليه، وهذا أولى له من التأخير من تأخير الإحرام إلى جدة ونحوها، بل يحرم وهو الواجب عليه، ويكون إحرامه في ثيابه، ويفدي هذه الفدية، لكن إذا أمكنه أن يخلعها ويبقى في السراويل؛ وجب عليه ذلك كما تقدم، نعم.","link":"https://binbaz.org.sa/fatwas/13460/ما-حكم-من-احرم-من-جدة-لعدم-توفر-ملابس-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64905.mp3","categories":["الإحرام","المواقيت"]},{"id":14948,"question":"أيضًا يقول: من أحرم بعمرة من ميقاته، ثم تحلل منها بعد أن أداها، ثم توجه لزيارة المسجد النبوي بالمدينة، وأثناء عودته إلى مكة دخلها بدون إحرام ظنًا منه أن الإحرام بالحج يكون يوم التروية من مكة.","title":"حكم من يعود إلى مكة من الحجاج دون إحرام بالحج","answer":"الجواب: هذا يقع من الناس كثيرًا ظنًا منهم أن تحللهم من العمرة كافٍ، ولا حاجة إلى أن يحرموا بعمرة أخرى، ولا بحج مبكر، والذي ينبغي في مثل هذا أنه إذا عاد من المدينة يعود بإحرام بحج أو بعمرة، وإذا كان الوقت مبكرًا عاد بعمرة ثانية، والعمرة فيها خير عظيم، قال النبي ﷺ: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة. فإذا عاد بعمرة أخرى كان خيرًا له، وإن عاد بحج وصبر على البقاء إلى وقت الحج فلا بأس؛ لأنه قد تحلل من العمرة، وإن قلبه إلى عمره وفسخه إلى عمرة، وتحلل منها، تحلل منه بالعمرة فلا بأس أيضًا إذا كان الوقت طويلًا. أما عوده بدون إحرام فلا ينبغي؛ لأن ظاهر النصوص تدل على أنه لا بد من إحرام، وهو قوله ﷺ لما وقت المواقيت: هن لهن، ولمن أتى عليهن، من غير أهلهن، ممن أراد الحج و العمرة وهذا قد قدم من المدينة يريد الحج، فظاهر النص: أنه يلزمه الإحرام، والقاعدة الشرعية الذي عليها جمهور أهل العلم أن من ترك الإحرام من الميقات وهو يلزمه وجب عليه دم، يذبح ويوزع في مكة المكرمة، فهذا وأشباهه إن فدوا يعني: أهدوا هديًا لأنهم تركوا الإحرام فهو أحوط لهم وأولى؛ لظاهر الأدلة، وظاهر كلام أهل العلم -رحمة الله عليهم-، والله  أعلم. ولا شك أن في الموضوع بعض الشبهة لهم؛ ولهذا قلنا: الأحوط لهم أن يهدوا؛ لأن لهم شبهة بأنهم قد حلوا من العمرة، وأتوا راجعين إلى مكة لينتظروا الحج، فهذه شبهة لهم؛ فلهذا في وجوب الهدي عليهم توقف، لكن بكل حال إذا أهدوا فهو أولى وأحوط. المقدم: طيب إذا تجاوز الحاج ميقاته هل له أن يأتي بحج مفرد؟ الشيخ: ما .. معنى هذا الكلام.\nالمقدم: مثلًا لو خرج للطائف أو للمدينة مثلًا خرج للطائف وهو من أهل نجد بعد أن اعتمر العمرة في أشهر الحج، فهل له أن يأتي بحج مفرد؟\nالشيخ: مثلما تقدم، مثلما تقدم في قصة أهل المدينة، إذا جاء من الطائف يحرم من ميقات الطائف بحج أو بعمرة ثانية، وكذلك الذي جاء من المدينة، أو جاء من اليمن، أو جاء من الشام أو غيره إذا عاد يحرم من الميقات بعمرة ثانية إذا كان الوقت واسعًا أو بالحج.\nالمقدم: لكن لو أحرم بالحج هل يلزمه هدي؟\nالشيخ: الصواب أنه يكون متمتعًا، وأن خروجه إلى الطائف، أو إلى المدينة ما يخرجه عن التمتع؛ لأنه في مواضع الحج، وفي موسم الحج في أشهر الحج على الصحيح، إلا إذا عاد إلى أهله، إذا عاد إلى أهله، ثم جاء بحج مفرد؛ فهذا يكون مفردًا للحج عند الأكثر؛ لأنه جاء عن عمر  وابنه أنهما قالا: فيمن ذهب إلى أهله، ثم عاد بحج أنه ليس بمتمتع، وأنه لا هدي عليه؛ لأن ذهابه إلى أهله خروج من عهدة العمرة السابقة، وانتقال منها إلى حاله الطبيعية الأولى، ثم عاد بالحج إلى مكة المكرمة فصار حجًا مفردًا، بخلاف الذي جاء للحج والعمرة، وبقي للحج والعمرة، لكنه تردد بين المدن المجاورة لمكة والقريبة منها، فهذا لم يخرج عن كونه جاء للحج وتمتع بالعمرة إلى الحج، نعم.","link":"https://binbaz.org.sa/fatwas/13454/حكم-من-يعود-الى-مكة-من-الحجاج-دون-احرام-بالحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64904.mp3","categories":["الإحرام"]},{"id":15089,"question":"أيضًا يقول: قضيت عامًا كاملًا بمكة، وجاءت فريضة الحج، والحمد لله أديت الفريضة، فهل علي فداء، أو صيام؟ أفتوني، وفقكم الله.كثير من الإخوان الذين من غير المملكة العربية السعودية؛ إذا كانوا مقيمين بالمملكة يتحرجون من تأدية الحج؛ لأنهم لم ينشؤوا النية من بلدهم الذي أتوا منه؟","title":"حكم الحج أو العمرة من مكة لمن لم ينوهما من بلده","answer":"الجواب: ليس عليك حرج في ذلك، ولا فدية عليك؛ إذا كنت لم تترك واجبًا من واجبات الحج، ولم تفعل محرمًا من المحرمات، فلا بأس عليك، ولا حرج في كونك أحرمت بالحج من مكة، إذا كنت جئت إلى مكة لعملٍ من الأعمال، ثم بدا لك الحج بعد ذلك، فلا حرج في ذلك، وهكذا العمرة، لو جئت إلى مكة لعملٍ من الأعمال، تجارة، أو غيرها، ثم بدا لك أن تعتمر؛ فإنه لا حرج عليك أن تعتمر من الحل، تخرج إلى أطراف مكة، إلى الحل، وتعتمر من التنعيم أو غيره، هذا لا بأس به. وأما الحج: فلا بأس أن تحرم به من نفس مكة، إذا كنت قدمتها بغير نية الحج والعمرة، وإنما قدمتها لعمل، ثم بدا لك أن تحج؛ فإنه لا حرج عليك أن تحرم من مكة بالحج، وحجك صحيح، إذا كملت ما يجب فيه، نعم.","link":"https://binbaz.org.sa/fatwas/13581/حكم-الحج-او-العمرة-من-مكة-لمن-لم-ينوهما-من-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65503.mp3","categories":["الإحرام"]},{"id":15164,"question":"ماذا يفعل الشخص الذي ينوي العمرة، ويكون قادمًا من مصر؟ هل يحرم من بيته أو من الطائرة، ولو كان في الطائرة ماذا يفعل بالضبط؟أفيدونا سماحة الشيخ.","title":"حكم من أحرم من بيته","answer":"الجواب: السنة أن يحرم من الميقات لا من بيته، إذا وازى الميقات، وهو في الطائرة أو السيارة، أو قبله بقليل أحرم، قال: اللهم لبيك عمرة، إن كان عمرة، أو: اللهم لبيك حجًا، إن كان حجًا، مع النية، مع نية القلب، نية القلب العمرة والحج ينوي بقلبه، ويتلفظ، ويقول: اللهم لبيك حجًا، إن كان حجًا، أو: اللهم لبيك عمرة، إن كان عمرة، من الميقات هذا هو الأفضل، وإن أحرم من بيته فلا بأس، أو من الطريق فلا بأس، لكن خلاف السنة، السنة أن يحرم من الميقات، ويكره أن يحرم قبل ذلك، لكن لو أحرم قبل ذلك انعقد إحرامه ولزمه، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13659/حكم-من-احرم-من-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56417.mp3","categories":["الإحرام"]},{"id":16467,"question":"الرسالة من الأخت أم أروى من شقراء، تقول: ما رأيكم في شخص توجه لزيارة أقارب له في مدينة جدة، وفي نيته أن يقوم بأداء العمرة إذا أتيحت له الفرصة لأداء العمرة، وعندما أتيحت له الفرصة أحرم من جدة، فهل ذلك مجزي؟ أم تنصحونه بشيء آخر؟ جزاكم الله خيرًا.","title":"حكم من أراد العمرة بعد أن تجاوز الميقات","answer":"الجواب: ليس عليه شيء ما دام نوى هذه النية إن أتيحت له الفرصة أحرم وإلا فلا، ما جزم، يكون بهذا غير جازم، فإذا يسر الله له الإحرام من جدة؛ فلا حرج.  أما الذي جزم بالعمرة من بلاده، سواء من المدينة، أو غيرها، هذا عليه أن يحرم من الميقات، إذا كان خرج من المدينة ناويًا جدة، ولكن ناويًا العمرة، جزم من المدينة أنه يعتمر؛ فعليه أن يحرم من الميقات، ميقات المدينة، ولا يجوز له أن يؤجل إلى جدة، فإن أجل؛ وجب عليه الرجوع إلى المدينة، ولا يجوز له أن يحرم من جدة، فإن أحرم من جدة؛ أثم، وعليه دم.  وهكذا لو كان في الطائف، وخرج إلى جدة ناويًا عمرة؛ يلزمه الرجوع إلى الميقات، فإن أحرم من جدة؛ فعليه دم يذبح في مكة للفقراء، أما الذي لا، ما جزم، بيقول: إن تيسر لي، إن سنحت الفرصة أحرمت؛ فهذا لا حرج عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15215/حكم-من-اراد-العمرة-بعد-ان-تجاوز-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81313.mp3","categories":["الإحرام","المواقيت"]},{"id":16680,"question":"هذا السؤال ورد من السائلة إيمان عبدالله من الطائف، لها سؤالان في الواقع تقول في الأول: هل يصح أن تحرم المرأة في ثياب بيض كما نشاهده كثيرًا؟ وما هو الأفضل في ذلك؟","title":"حكم لبس المرأة ثيابًا بيضاء عند الإحرام","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن السنة للمرأة أن تحرم في ملابس غير جميلة، وغير لافتة للنظر، تحرم في ملابس، ليس فيها فتنة لأحد، أما البيض ففيها نظر؛ لأن فيها تشبه بالرجال، إلا إذا كانت على هيئة لا تشبه الرجال، كأن يكون فيها نقط، يلبسها النساء في العادة، أو خياطها في جيبها، ويديها، وتفصيلها يخالف طريقة الرجال؛ فلا بأس. والأفضل أن تكون ملابسها خافتة، ليس فيها ما يلفت النظر، والبيض قد تلفت النظر، فينبغي أن تكون ملابسًا ليس فيها ما يلفت النظر، ولا تسبب الافتتان بها من الرجال، نعم.","link":"https://binbaz.org.sa/fatwas/15404/حكم-لبس-المراة-ثيابا-بيضاء-عند-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_818/nour_81801.mp3","categories":["الإحرام","قضايا المرأة"]},{"id":16728,"question":"يسأل سؤالًا آخر فيقول: بالنسبة للعمرة هل هناك إثم على من يعتمر بإحرام واحد أكثر من مرة؟ وهل يستحب عند كل مرة تغيير الإحرام؟ وما المدة بين كل عمرة وأخرى؟ هل لها مدة معينة؟ وما هي الأدعية الصحيحة عن النبي ﷺ حين دخول مكة؟ جزاكم الله خيرًا.","title":"أدعية العمرة وحكم تغيير الإحرام لكل عمرة","answer":"الجواب: لا حرج أن يحرم في ملابس الإحرام مرات، وليس لهذا حد، وإذا توسخت، وغسلها، ثم أحرم فيها؛ فلا بأس والحمد لله، وليس هناك حد معلوم بين العمرتين، فلو اعتمر في الشهر مرتين، أو أكثر، فلا بأس لقول النبي ﷺ: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة. وقد اعتمرت عائشة في حجة الوداع -رضي الله عنها- عمرتين في أقل من عشرين يومًا: عمرة وهي داخلة من المدينة، وعمرة بعد ذلك في ليلة الثالثة عشرة من ذي الحجة ليلة ... فالأمر في هذا واسع، والحمد لله. والدعوات يدعو الإنسان بما يسر الله في طوافه، في سعيه، يدعو بما تيسر، يلبي عند الإحرام: لبيك اللهم لبيك، أولًا يقول: لبيك عمرة مثلما يقول: لبيك حجًا، ثم يلبي التلبية الشرعية: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد، والنعمة لك والملك، لا شريك لك هذه التلبية الشرعية: لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك في الطريق حتى يصل إلى المسجد الحرام إلى الكعبة. ثم يشرع في الطواف، ويكبر عند استقبال الحجر، يقول: الله أكبر، ثم يشرع في الطواف، يقول: اللهم إيمانًا بك، وتصديقًا بكتابك، ووفاء بعهدك، واتباعًا لسنة نبيك محمد ﷺ. أو يقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر ولا حول ولا قوة إلا بالله أو سبحان الله وبحمده، سبحان الله العظيم، لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير ويصلي على النبي ﷺ ويكثر من ذلك. ويدعو بما أحب: اللهم اغفر لي، وارحمني، اللهم إني أسألك رضاك والجنة، وأعوذ بك من سخطك والنار، اللهم أصلح قلبي وعملي، اللهم اغفر لي ولوالدي؛ إذا كان والداه مسلمين، اللهم اجعلها عمرة مقبولة، أو حجًا مقبولًا إن كان حجًا. وهكذا يتخير الدعوات الطيبة، ويدعو في طوافه، وفي سعيه، وإذا جاء عند الركن اليماني؛ استلمه بيده اليمنى، وقال: باسم الله الله أكبر، فإن كان ما حصل يمشي، لا يشير إليه، ثم يقول: ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار في آخر كل شوط بين الركنين بعد اليماني، يختم كل شوط بهذا الدعاء: ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار هذا هو الأفضل؛ تأسيًا بالنبي -عليه الصلاة والسلام- ثم إذا وازى الحجر يقول: الله أكبر، حتى يكمل السبعة، يكبر في أولها، وفي آخرها، كما فعله النبي، عليه الصلاة والسلام. وإذا كان في طواف القدوم أول ما يقدم يرمل في الثلاثة الأول: الأول، والثاني، والثالث يرمل يعني: يهرول في الثلاثة الأول إذا كان رجلًا، ثم يمشي في الأربعة، أما المرأة فلا تهرول، تمشي مشيًا في السبعة كلها؛ لأنها عورة.  وهكذا السعي يكبر على الصفا والمروة ثلاث مرات، يدعو ثلاث مرات، ويرفع يديه مستقبلًا القبلة على الصفا والمروة، الرجل والمرأة جميعًا. وعليه أيضًا يستحب له في بطن الوادي أن يرمل في السعي، يعني: يهرول قليلًا في المسعى بين العلمين، وبطن الوادي مثلما فعله النبي ﷺ في كل شوط، يعني: في بطن الوادي بين العلمين، الرجل خاصة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15488/ادعية-العمرة-وحكم-تغيير-الاحرام-لكل-عمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76112.mp3","categories":["الإحرام"]},{"id":16946,"question":"بعض الحجاج قدم عن طريق البحر، فأحرم من الميقات، ولما وصل إلى جدة خلع الإحرام، وأقام بعض أيام، ثم أحرم مجددًا من جدة، ماذا على من فعل مثل هذا العمل؟","title":"حكم خلع الحاج ملابس الإحرام","answer":"الجواب: هو على إحرامه، وخلعه للإحرام لا يجعله حلالًا، بل هو جهل منه، وعليه الاستمرار في الإحرام الذي أحرم به من الميقات، وخلعه لملابس الإحرام لا يجعله حلالًا، وليس عليه شيء، إذا كان جاهلًا، ليس عليه شيء؛ لأجل جهله؛ لأن النبي ﷺ قال لرجلٍ أحرم في الجبة، وتضمخ بالطيب، قال له ﷺ: اخلع عنك الجبة، واغسل عنك أثر الخلوق، واصنع في عمرتك ما كنت صانعًا في حجك ولم يأمره بفدية؛ لأجل الجهل، فهذا الذي خلع الملابس، ولبس المخيط، أو العمامة على رأسه، ليس عليه شيء، وهو على إحرامه؛ بسبب الجهل. أما إن كان يعلم أن هذا لا يجوز له، وفعله تساهلًا؛ فهذا عليه فدية عن لبس المخيط، وعن غطائه رأسه، إن كان غطى رأسه، وهي صيام ثلاثة أيام، أو إطعام ستة مساكين لكل مسكين نصف صاع، أو ذبح شاة، عن لباس المخيط، وهكذا عن غطاء الرأس، مع التوبة والاستغفار. وهكذا أمر النبي ﷺ كعب بن عجرة لما أمره أن يحلق رأسه، أمره أن يكفر بهذه الكفارة، وذكر أهل العلم أن حكم لباس المخيط، وغطاء الرأس، والطيب وقلم الأظفار، حكمه حكم حلق الشعر، فيه الفدية المذكورة، وهي صيام ثلاثة أيام، أو إطعام ستة مساكين، لكل مسكين نصف صاع من قوت البلد، من تمرٍ، أو حنطةٍ، أو أرزٍ، أو شعير، ونحو ذلك، أو ذبح شاة، ويقوم مقامها سبع بدنة، أو سبع بقرة.  فإن كان عنده زوجة ووطئها؛ أفسد حجه، فعليه أن يتمم حجه حجًا فاسدًا، يجب عليه أن يتم حجه، ثم يقضي في المستقبل حجةً أخرى، بدل الحج الذي أفسده، وعليه بدنة، تذبح في مكة للفقراء، بسبب عمله السيئ، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15735/حكم-خلع-الحاج-ملابس-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82802.mp3","categories":["الإحرام"]},{"id":17328,"question":"السائلة من جمهورية مصر العربية، ومقيمة بالدمام تقول: نويت الإحرام من الميقات، ثم بعد ذلك.. هذه المرأة نوت الإحرام من الميقات، ثم بعد ذلك نزل عليها الحيض قبل الوقوف بعرفة، ثم طهرت في اليوم الحادي عشر، وسعت، وطافت بدون إعادة للإحرام أي: أنها لم تذهب مرة أخرى للميقات لتجدد إحرامها بعد أن طهرت، فهل فعلها صحيح؟","title":"حكم من أتاها الحيض بعد الإحرام","answer":"الجواب: نعم فعلها صحيح، وليس هناك حاجة للتجديد، فهي أحرمت من الميقات، ثم أصابها الحيض، تبقى على إحرامها، وتفعل أفعال الحج ما عدا الطواف، والسعي يؤجل، فتقف مع الناس بعرفة، وفي مزدلفة، وترمي الجمار، وتقص من رأسها، وتحل، فإذا طهرت؛ طافت، وسعت والحمد لله، وليس عليها أن تعيد الإحرام، إحرامها من الميقات كافٍ، والحيض لا يبطل الإحرام، الإحرام باقٍ، ولكن يمنع من الطواف. وهكذا النفاس لو ولدت في عرفة، أو بعد عرفة؛ تفعل أفعال الحج كلها، إلا الطواف، والسعي تؤجل حتى تطهر. نعم.  المقدم: سماحة الشيخ! حتى ولو لم تكن قد اشترطت؟ الشيخ: نعم؟ المقدم: حتى ولو لم تكن قد اشترطت، تقول: وهل إن اشترطت عند نيتها للإحرام، ثم جاءتها الحيضة يلزمها إعادة الإحرام بعد الطهر؟ الشيخ: إذا كانت شرطت لها الحل لها التحلل إذا كانت اشترطت، قالت: محلي حيث حبستني .... مقصودها من الحيض يعني: إذا أصابها الحيض تحل، فهذا لها الحل، أما إذا ما قصدها هذا القصد تخاف من أن يصيبها مرض، أو نحوه، فالحيض ليس بمانع، الحيض، حجت عائشة، وأصابها الحيض قبل دخول مكة، وأمرها النبي ﷺ أن تفعل ما يفعل الحجاج إلا الطواف. فالمقصود: أنها إذا قالت: محلي حيث حبستني عند الإحرام، قالت: إن حبسني حابس فمحلي حيث حبستني، هذا إذا منعها مرض، أو منعها عدو؛ لها أن تحل، أما الحيض لا يمنعها، لكن لو كانت تقصد الحيض جاءت للعمرة مثلًا، ومعها رفاق، فأحرمت بالعمرة، وقالت: إن حبسني حابس، ومقصودها حتى الحيض إذا حبسها حتى تحل، وترجع مع أصحابها، فهي على نيتها، أما الحيض ما يمنع الحج، ولو قالت: إن حبسني حابس، الحيض تمشي تمضي في حجها، وإذا طهرت تطوف، وتسعى، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16169/حكم-من-اتاها-الحيض-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76907.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":17333,"question":"السائلة من جمهورية مصر العربية، ومقيمة بالدمام تقول: نويت الإحرام من الميقات، ثم بعد ذلك.. هذه المرأة نوت الإحرام من الميقات، ثم بعد ذلك نزل عليها الحيض قبل الوقوف بعرفة، ثم طهرت في اليوم الحادي عشر، وسعت، وطافت بدون إعادة للإحرام أي: أنها لم تذهب مرة أخرى للميقات لتجدد إحرامها بعد أن طهرت، فهل فعلها صحيح؟","title":"حكم من أتاها الحيض بعد الإحرام","answer":"الجواب: نعم فعلها صحيح، وليس هناك حاجة للتجديد، فهي أحرمت من الميقات، ثم أصابها الحيض، تبقى على إحرامها، وتفعل أفعال الحج ما عدا الطواف، والسعي يؤجل، فتقف مع الناس بعرفة، وفي مزدلفة، وترمي الجمار، وتقص من رأسها، وتحل، فإذا طهرت؛ طافت، وسعت والحمد لله، وليس عليها أن تعيد الإحرام، إحرامها من الميقات كافٍ، والحيض لا يبطل الإحرام، الإحرام باقٍ، ولكن يمنع من الطواف. وهكذا النفاس لو ولدت في عرفة، أو بعد عرفة؛ تفعل أفعال الحج كلها، إلا الطواف، والسعي تؤجل حتى تطهر. نعم.  المقدم: سماحة الشيخ! حتى ولو لم تكن قد اشترطت؟ الشيخ: نعم؟ المقدم: حتى ولو لم تكن قد اشترطت، تقول: وهل إن اشترطت عند نيتها للإحرام، ثم جاءتها الحيضة يلزمها إعادة الإحرام بعد الطهر؟ الشيخ: إذا كانت شرطت لها الحل لها التحلل إذا كانت اشترطت، قالت: محلي حيث حبستني .... مقصودها من الحيض يعني: إذا أصابها الحيض تحل، فهذا لها الحل، أما إذا ما قصدها هذا القصد تخاف من أن يصيبها مرض، أو نحوه، فالحيض ليس بمانع، الحيض، حجت عائشة، وأصابها الحيض قبل دخول مكة، وأمرها النبي ﷺ أن تفعل ما يفعل الحجاج إلا الطواف. فالمقصود: أنها إذا قالت: محلي حيث حبستني عند الإحرام، قالت: إن حبسني حابس فمحلي حيث حبستني، هذا إذا منعها مرض، أو منعها عدو؛ لها أن تحل، أما الحيض لا يمنعها، لكن لو كانت تقصد الحيض جاءت للعمرة مثلًا، ومعها رفاق، فأحرمت بالعمرة، وقالت: إن حبسني حابس، ومقصودها حتى الحيض إذا حبسها حتى تحل، وترجع مع أصحابها، فهي على نيتها، أما الحيض ما يمنع الحج، ولو قالت: إن حبسني حابس، الحيض تمشي تمضي في حجها، وإذا طهرت تطوف، وتسعى، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16169/حكم-من-اتاها-الحيض-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76907.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":17707,"question":"من أسئلة السائلة أم محمد من مدينة الزلفي تقول: يا سماحة الشيخ لقد نوت العمرة واغتسلت من مدينة الزلفي، تقول: فلما وصلت الميقات- السيل الكبير- أنا وأهلي أردت أن أغتسل مرةً ثانية، فلما وضعت الصابون على جسمي وفتحت الماء فإذا هو بارد وخشيت على نفسي؛ فتركت الاغتسال ومسحت الصابون الذي على جسمي بالفوطة، ثم أديت العمرة، هل عمرتي صحيحة؟","title":"حكم الغسل قبل الإحرام","answer":"الجواب: نعم، الغسل ما هو بواجب مستحب والغسل في البيت كاف، الغسل في البيت كاف والحمد لله، والغسل ما هو بواجب ليس بواجب، ولكنه مستحب في الحج والعمرة قبل الإحرام، إذا تيسر ذلك وليس بلازم، الحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16660/حكم-الغسل-قبل-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59522.mp3","categories":["الإحرام"]},{"id":17782,"question":"يقول: هل صحيح بأنك عندما تريد عقد نية الإحرام سواء كان ذلك للعمرة أو للحج بأنه لا بد أن تمسك بكل شيء تريد أن تستخدمه أثناء الإحرام من نقود ولوازم شخصية؟","title":"حكم لمس الأشياء التي ستستخدم أثناء الإحرام","answer":"الجواب: ليس لهذا أصل، بل يحرم ويلبس ملابس الإحرام ويلبي بالعمرة أو الحج وما جاز له فعله فعله ولو ما أحضره عند الإحرام، له أن يجعل النقود في إزاره أو شيء من الحاجات ولو ما استحضرها عند الإحرام، هذا شيء لا أصل له، إنما يغتسل أفضل ويتوضأ، ويصلي ركعتين إذا تيسر، ويلبي بالعمرة أو بالحج وينويها بقلبه ويقول: اللهم لبيك عمرة، وإن كان حجًا اللهم لبيك حجًا ولو ما استحضر الأشياء اللي بيشيلها معه، وإذا استحضرها بعد ذلك بعدما ركب طلب النقود أو طلب متاعًا آخر وحمله معه لا شيء في هذا والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16770/حكم-لمس-الاشياء-التي-ستستخدم-اثناء-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77809.mp3","categories":["الإحرام"]},{"id":17861,"question":"هذه الأخت من مكة المكرمة، ورمزت لاسمها بـ (ع. ع. ع) تقول سماحة الشيخ: قرأت في أحد الكتب بأنه يسن الإحرام بالحج من تحت الميزاب، فما هو الميزاب؟ وما مدى صحة ذلك؟","title":"ما حكم الإحرام من تحت الميزاب؟","answer":"الجواب: الصواب أنه يحرم بالحج من بيته، أهل مكة المقيمون بمكة والمحلون بمكة يحرمون من بيوتهم، ولا يحرمون من تحت الميزاب، وليس عليه دليل. والميزاب هو المرزام الذي يصب معه السيل من سطح الكعبة على الحجر، هذا يقال له الميزاب، يعني: المرزام، اللي يسمونه الناس المرزام. نعم.","link":"https://binbaz.org.sa/fatwas/16870/ما-حكم-الاحرام-من-تحت-الميزاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59806.mp3","categories":["الإحرام"]},{"id":17992,"question":"من أحد الإخوة المستمعين هو أحمد محمد عوض من الرياض يقول: أنا مقيم في مدينة الرياض هل يجوز لي زيارة أحد الأقارب في جدة ثم الإحرام من جدة كأهلها بنية أداء العمرة مع العلم بأن سبب سفري كان لأداء العمرة وزيارة هذا القريب في وقت واحد، ولقد سافرت بالطائرة مباشرة إلى جدة؟ أفيدونا جزاكم الله خيرًا.الشيخ: تعيده، الله المستعان.المقدم: يقول: أنا مقيم بمدينة الرياض هل يجوز لي زيارة أحد الأقارب في جدة ثم الإحرام من جدة كأهلها بنية أداء العمرة، مع العلم بأن سبب سفري كان لأداء العمرة وزيارة هذا القريب في وقت واحد، ولقد سافرت بالطائرة مباشرة إلى جدة؟","title":"حكم الإحرام من جدة لمن ليس من أهلها","answer":"الجواب: ما دمت تقصد العمرة والزيارة جميعًا من نفس بلدك فالواجب عليك أن تحرم من الميقات، أما إذا كنت ما قصدت إلا الزيارة، ثم بدا لك أن تعتمر فاحرم من جدة لا بأس، أما ما دمت قد عزمت على العمرة مع الزيارة من بلدك فعليك أن تحرم من الميقات لقوله ﷺ لما وقت المواقيت: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج أو العمرة وهذا محل إجماع بين أهل العلم ليس فيه خلاف والحمد لله. نعم.\nالمقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17031/حكم-الاحرام-من-جدة-لمن-ليس-من-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84916.mp3","categories":["الإحرام","المواقيت"]},{"id":18402,"question":"في آخر أسئلة هذا السائل يذكر ويقول: شاهدت بعض الحجاج في عرفة ومنى يقومون بنزع الإحرام من أجل الاستحمام، وبعد الانتهاء من ذلك يلبسون الإحرام مرة أخرى، فهل هذا جائز؟","title":"حكم نزع الإحرام لغرض الاستحمام","answer":"الجواب: نعم لا حرج، كون الإنسان ينزع الإحرام للتروش أو للحر، يطرح الرداء عن ظهره من أجل الحر، ثم يعيده لا بأس، أو عند إرادة التروش والتبرد ينزع الإحرام، الإزار والرداء ثم يتروش، ثم يعيدهما كل هذا لا بأس به والحمد لله .نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17472/حكم-نزع-الاحرام-لغرض-الاستحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78411.mp3","categories":["الإحرام"]},{"id":18544,"question":"يقول: قمتُ بأداء فريضة العمرة، وهي العمرة الأولى لي، أثناء أداء العمرة، وأنا في مكة المكرمة، قمت بحل الإحرام بعد أداء العمرة، وخرجت إلى ميقات خارج مكة، وقمت مرة أخرى بلبس الإحرام لأداء عمرة لوالدتي المتوفاة، وذلكم في يوم واحد، فهل ما فعلته صحيح؟","title":"حكم الخروج إلى الحل لأداء عمرة عن الغير","answer":"الجواب: لا حرج في ذلك إن كان يؤدي العمرة، ثم يخرج إلى التنعيم أو الجعرانة أوعرفة -إلى الحل يعني- ثم يحرم بعمرة لأبيه أو لغيره لا بأس، هذا الصواب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17646/حكم-الخروج-الى-الحل-لاداء-عمرة-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73317.mp3","categories":["الإحرام"]},{"id":18690,"question":"هذا السائل الذي رمز لاسمه بـ (ش. م. ع) من مصر يقول في هذا  سماحة الشيخ! أنا أديت فريضة الحج، وفي نية حجي متمتع، ولكن عند إحرامي من الميقات قلت: لبيك اللهم حج وعمرة، ولكنني وأنا في الطريق إلى مكة قرأتُ كتيبًا من مناسك الحج، فعلمتُ بأن للعمرة إحرامًا، والحج إحرامًا، فغيرت نيتي وأنا في الطريق، وقلت: لبيك اللهم عمرة، فهل حجي صحيح؟","title":"حكم من أهلَّ بحج وعمرة وبعد الميقات أهلَّ بالعمرة فقط","answer":"الجواب: إذا قال الإنسان: لبيك حج وعمرة، فالأفضل أن يتحلل بالعمرة، فإذا تحللت بعمرة، طفت، وسعيت، وقصرت كنت متمتعًا، والحمد لله، وهذا هو الأفضل، والذي فعلته هو الأفضل، ثم تحج مع الناس، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17804/حكم-من-اهل-بحج-وعمرة-وبعد-الميقات-اهل-بالعمرة-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78809.mp3","categories":["الإحرام"]},{"id":18751,"question":"هذه السائلة أم سلام من مكة المكرمة تسأل عن العمرة: من أين يحرم لها من المنزل أو من مسجد التنعيم بالنسبة لسكان مكة المكرمة فضيلة الشيخ؟","title":"موضع الإحرام لأهل مكة لمن أراد العمرة","answer":"الجواب: إذا أراد العمرة من هو ساكن في مكة يخرج إلى الحل: التنعيم، أو عرفات، أو الجعرانة أو غيرها، النبي ﷺ لما أراد العمرة وهو في أطراف مكة أحرم من الجعرانة، واعتمر عام الفتح، ولما أرادت عائشة العمرة وهي في مكة أمرها أن تخرج إلى الحل، أمر عبد الرحمن أخاها أن يخرج بها إلى الحل، فأحرمت من التنعيم، هذا هو السنة لأهل مكة، إذا أرادوا العمرة يخرجون خارج الحرم: عرفات، الجعرانة، التنعيم، يعني: خارج الحرم، يحرم بالعمرة ثم يدخل. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17880/موضع-الاحرام-لاهل-مكة-لمن-اراد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79008.mp3","categories":["الإحرام","المواقيت"]},{"id":19255,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الدمام، وباعثها المستمع عبد القادر بن البناء، الأخ عبد القادر يقول: قدمت من مصر لأجل عمل عمرة وركبت المركب، ونزلت في جدة عند أخي الذي يعمل هناك، ولم يكن معي ملابس إحرام، وبعد يومين من جلوسي عند أخي اشترى لي ملابس الإحرام وذهبت وعملت عمرة، فهل العمرة صحيحة؟ وهل علي دم أو لا؟","title":"حكم من جاوز الميقات من دون إحرام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كنت نويت العمرة من بلادك فعليك دم؛ لأنك أحرمت من دون الميقات، ميقاتك رابغ وما يحاذيه، وقد جاوزته بدون إحرام؛ فعليك دم يذبح في مكة للفقراء مثل الضحية وهي رأس من الغنم، جذع ضأن أو ثني معز، يذبح للفقراء؛ لأنك تركت الواجب وهو الإحرام من الميقات والعمرة صحيحة والحمد لله، العمرة صحيحة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18448/حكم-من-جاوز-الميقات-من-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73901.mp3","categories":["الإحرام","المواقيت"]}]
